static inline CtrColor makeColor(uint32_t bgr, float alpha) {
    CtrColor c;
    c.r = (uint8_t) BGR_R(bgr);
    c.g = (uint8_t) BGR_G(bgr);
    c.b = (uint8_t) BGR_B(bgr);
    if (0.0f >= alpha) c.a = 0;
    else if (alpha >= 1.0f) c.a = 255;
    else c.a = (uint8_t) (alpha * 255.0f + 0.5f);
    return c;
}

static int32_t nextPow2(int32_t v) {
    int32_t p = 8;
    while (v > p) p <<= 1;
    return p;
}

static CtrSurface* getSurface(CtrRenderer* r, int32_t id) {
    if (0 > id || (uint32_t) id >= r->surfaceCount) return nullptr;
    CtrSurface* s = &r->surfaces[id];
    return s->used ? s : nullptr;
}

// The bound surface if it is a windowed one (see CtrSurface.windowed).
static CtrSurface* boundWindow(CtrRenderer* r) {
    if (r->boundTarget == nullptr) return nullptr;
    CtrSurface* s = getSurface(r, r->boundSurface);
    return s != nullptr && s->windowed ? s : nullptr;
}

