static GPU_BLENDFACTOR blendFactorToGpu(int32_t factor) {
    switch (factor) {
        case bm_zero: return GPU_ZERO;
        default:
        case bm_one: return GPU_ONE;
        case bm_src_color: return GPU_SRC_COLOR;
        case bm_inv_src_color: return GPU_ONE_MINUS_SRC_COLOR;
        case bm_src_alpha: return GPU_SRC_ALPHA;
        case bm_inv_src_alpha: return GPU_ONE_MINUS_SRC_ALPHA;
        case bm_dest_alpha: return GPU_DST_ALPHA;
        case bm_inv_dest_alpha: return GPU_ONE_MINUS_DST_ALPHA;
        case bm_dest_color: return GPU_DST_COLOR;
        case bm_inv_dest_color: return GPU_ONE_MINUS_DST_COLOR;
        case bm_src_alpha_sat: return GPU_SRC_ALPHA_SATURATE;
    }
}

// GameMaker's blend modes as the GL renderers implement them, expressed in bm_* factors.
static void blendModeFactors(int32_t mode, int32_t* src, int32_t* dst) {
    switch (mode) {
        default:
        case bm_normal: *src = bm_src_alpha; *dst = bm_inv_src_alpha; break;
        case bm_add: *src = bm_src_alpha; *dst = bm_one; break;
        case bm_subtract: *src = bm_zero; *dst = bm_inv_src_color; break;
        case bm_reverse_subtract: *src = bm_src_alpha; *dst = bm_one; break;
        case bm_min: *src = bm_one; *dst = bm_one; break;
        case bm_max: *src = bm_src_alpha; *dst = bm_inv_src_color; break;
    }
}

static void applyBlend(CtrRenderer* r) {
    if (!r->blendEnable) {
        C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_ONE, GPU_ZERO, GPU_ONE, GPU_ZERO);
        return;
    }
    BlendFactors* f = &r->base.blendFactors;
    GPU_BLENDEQUATION eq = GPU_BLEND_ADD;
    if (r->blendMode == bm_reverse_subtract) eq = GPU_BLEND_REVERSE_SUBTRACT;
    else if (r->blendMode == bm_min) eq = GPU_BLEND_MIN;
    C3D_AlphaBlend(eq, eq, blendFactorToGpu(f->src), blendFactorToGpu(f->dst), blendFactorToGpu(f->srcAlpha), blendFactorToGpu(f->dstAlpha));
}

