    snprintf(batch.text, sizeof(batch.text), "%s%s", r->trace.desc[0] != '\0' ? r->trace.desc : "(nothing in view)", special ? " (special)" : "");
    if (!CTR_ARRAY_PUT(r->trace.batches, batch)) return;
    if (!special && r->gameProjection) splitFrame(r);
