// What the memory at addr is: a surface's texture, a scratch, a screen.
static void traceMemoryName(const CtrRenderer* r, uint32_t addr, char* out, size_t size) {
    for (uint32_t i = 0; r->surfaceCount > i; i++) {
        const CtrSurface* s = &r->surfaces[i];
        uint32_t data = (uint32_t) (uintptr_t) s->tex.data;
        if (s->used && data != 0 && addr >= data && data + s->tex.size > addr) {
            snprintf(out, size, "surface %u %dx%d%s+%u", (unsigned) i, (int) s->width, (int) s->height, s->spilled ? " (fcram)" : "", (unsigned) (addr - data));
            return;
        }
    }
    for (ptrdiff_t k = 0; arrlen(r->scratches) > k; k++) {
        const CtrScratch* sc = &r->scratches[k];
        uint32_t data = (uint32_t) (uintptr_t) sc->tex.data;
        if (sc->target != nullptr && data != 0 && addr >= data && data + sc->tex.size > addr) {
            snprintf(out, size, "scratch %d %ux%u+%u", (int) k, (unsigned) sc->tex.width, (unsigned) sc->tex.height, (unsigned) (addr - data));
            return;
        }
    }
    snprintf(out, size, "%08x%s", (unsigned) addr, addr >= OS_VRAM_VADDR && OS_VRAM_VADDR + OS_VRAM_SIZE > addr ? " (vram)" : "");
}

static void traceBegin(CtrRenderer* r) {
    r->trace.wanted = false;
    CtrGpu_waitIdle();
    arrsetlen(r->trace.batches, 0);
    r->trace.active = true;
    CtrGpu_traceStart();
}

// After the frame's C3D_FrameEnd: waits for the GPU and logs what it ran.
static void traceEnd(CtrRenderer* r) {
    if (!r->trace.active) return;
    r->trace.active = false;
    CtrGpu_waitIdle();
    static CtrGpuTraceOp ops[CTR_GPU_TRACE_MAX];
    static gxCmdEntry_s entries[CTR_GPU_TRACE_MAX];
    uint32_t entryCount = 0;
    uint32_t opCount = CtrGpu_traceTake(ops, entries, &entryCount);
    logInfo("[gputrace] frame %u: %u GX commands, %u finished, %u batches\n", (unsigned) r->frame, (unsigned) entryCount, (unsigned) opCount,
            (unsigned) arrlen(r->trace.batches));
    static const char* const kindNames[CTR_GPU_OP_KINDS] = { "list", "fill", "copy" };
    double sums[CTR_GPU_OP_KINDS] = { 0 };
    uint32_t op = 0;
    ptrdiff_t batch = 0;
    char from[96], to[96];
    for (uint32_t e = 0; entryCount > e; e++) {
        const uint32_t* d = entries[e].data;
        uint32_t type = d[0] & 0xFF;
        int kind = type == 1 ? CTR_GPU_OP_DRAW : type == 2 ? CTR_GPU_OP_FILL : (type == 3 || type == 4) ? CTR_GPU_OP_COPY : -1;
        if (kind < 0) continue; // cache flushes signal nothing
        // A fill of two buffers finishes twice.
        int events = type == 2 && d[4] != 0 && d[1] != 0 ? 2 : 1;
        double ms = 0.0;
        bool matched = true;
        for (int k = 0; events > k; k++) {
            if (op >= opCount || ops[op].kind != kind) {
                matched = false;
                break;
            }
            ms += (double) ops[op].ticks / CPU_TICKS_PER_MSEC;
            op++;
        }
        sums[kind] += ms;
        const char* flag = matched ? "" : " (no matching finish)";
        if (type == 1) {
            uint32_t addr = d[1], end = d[1] + d[2];
            logInfo("[gputrace] %3u %s %7.3f ms, %u words%s\n", (unsigned) e, kindNames[kind], ms, (unsigned) (d[2] / 4), flag);
            while (arrlen(r->trace.batches) > batch) {
                uint32_t cmd = (uint32_t) (uintptr_t) r->trace.batches[batch].cmd;
                if (cmd < addr || cmd >= end) break;
                logInfo("[gputrace]       batch %s\n", r->trace.batches[batch].text);
                batch++;
            }
        } else if (type == 2) {
            traceMemoryName(r, d[1], to, sizeof(to));
            logInfo("[gputrace] %3u %s %7.3f ms, %s, %u KB, value %08x%s%s\n", (unsigned) e, kindNames[kind], ms, to, (unsigned) ((d[3] - d[1]) / 1024),
                    (unsigned) d[2], d[4] != 0 ? " and a second buffer" : "", flag);
        } else {
            traceMemoryName(r, d[1], from, sizeof(from));
            traceMemoryName(r, d[2], to, sizeof(to));
            logInfo("[gputrace] %3u %s %7.3f ms, %s, %s to %s, %u KB%s\n", (unsigned) e, kindNames[kind], ms, type == 3 ? "transfer" : "texture copy", from, to,
                    type == 4 ? (unsigned) (d[3] / 1024) : 0u, flag);
        }
    }
    if (arrlen(r->trace.batches) > batch) logInfo("[gputrace] %d batches not found in any list\n", (int) (arrlen(r->trace.batches) - batch));
    logInfo("[gputrace] totals: lists %.2f ms, fills %.2f ms, copies %.2f ms, %u finishes unmatched\n", sums[0], sums[1], sums[2], (unsigned) (opCount - op));
}
