// ===[ Texture probe ]===
// A diagnostic, off unless the game folder has texprobe.txt (main.c): tiles
// and palette copies note a hash of their texels when made, and at the frames
// listed there every resident tile and copy is checked against it
// ("[texcheck]"). At frames listed negated, each batch is listed too
// ("[texprobe]"): its box on the target, and each texture it draws with,
// what that is and the hash of its texels as the batch is recorded.

static void probeName(CtrRenderer* r, const C3D_Tex* tex, char* out, size_t size, uint32_t* made) {
    *made = 0;
    if (tex == &r->white) {
        snprintf(out, size, "white");
        return;
    }
    CtrTextureCache* cache = &r->textures;
    for (uint32_t p = 0; cache->pageCount > p; p++) {
        CtrPage* page = &cache->pages[p];
        if (!page->layoutKnown || page->tiles == nullptr) continue;
        for (int32_t i = 0; page->tilesX * page->tilesY > i; i++) {
            CtrTile* t = &page->tiles[i];
            if (&t->tex != tex && t->mirror != tex) continue;
            snprintf(out, size, "%s %u/%d%s used %u", t->mirror == tex ? "mirror" : "tile", (unsigned) p, (int) i, t->valid ? "" : " (not resident)",
                     (unsigned) t->lastUsedFrame);
            *made = t->probeHash;
            return;
        }
    }
    for (ptrdiff_t i = 0; arrlen(r->palCopies) > i; i++) {
        CtrPalCopy* c = r->palCopies[i];
        for (int k = 0; 2 > k; k++) {
            if (&c->tex[k] != tex) continue;
            snprintf(out, size, "pal %d/%d %c%s%s%s %dx%d at %d,%d used %u", (int) c->pageId, (int) c->tile, k == 0 ? 'x' : 'y', c->mixed ? " mixed" : "",
                     c->stale ? " stale" : "", c->has[k] ? "" : " (not made)", (int) c->w, (int) c->h, (int) c->x, (int) c->y, (unsigned) c->lastUsedFrame);
            *made = c->probeHash[k];
            return;
        }
    }
    for (uint32_t i = 0; r->surfaceCount > i; i++) {
        if (&r->surfaces[i].tex == tex) {
            snprintf(out, size, "surface %u", (unsigned) i);
            return;
        }
    }
    snprintf(out, size, "other");
}

