// Checks every resident tile and palette copy against its hash when made.
static void probeCheckAll(CtrRenderer* r) {
    CtrTextureCache* cache = &r->textures;
    uint32_t checked = 0, bad = 0;
    for (uint32_t p = 0; cache->pageCount > p; p++) {
        CtrPage* page = &cache->pages[p];
        if (!page->layoutKnown || page->tiles == nullptr) continue;
        for (int32_t i = 0; page->tilesX * page->tilesY > i; i++) {
            CtrTile* t = &page->tiles[i];
            if (!t->valid || t->probeHash == 0) continue;
            checked++;
            uint32_t now = CtrTextures_hashTexels(&t->tex);
            if (now == t->probeHash) continue;
            bad++;
            logInfo("[texcheck] f%u tile %u/%d changed since loaded: %08x now %08x, data %08x, %u bytes, used %u\n", (unsigned) r->frame, (unsigned) p, (int) i,
                    (unsigned) t->probeHash, (unsigned) now, (unsigned) (uintptr_t) t->tex.data, (unsigned) t->tex.size, (unsigned) t->lastUsedFrame);
        }
    }
    for (ptrdiff_t i = 0; arrlen(r->palCopies) > i; i++) {
        CtrPalCopy* c = r->palCopies[i];
        if (0 > c->pageId) continue;
        for (int k = 0; 2 > k; k++) {
            if (!c->has[k] || c->probeHash[k] == 0) continue;
            checked++;
            uint32_t now = CtrTextures_hashTexels(&c->tex[k]);
            if (now == c->probeHash[k]) continue;
            bad++;
            logInfo("[texcheck] f%u pal %d/%d %c changed since made: %08x now %08x, data %08x, used %u\n", (unsigned) r->frame, (int) c->pageId, (int) c->tile,
                    k == 0 ? 'x' : 'y', (unsigned) c->probeHash[k], (unsigned) now, (unsigned) (uintptr_t) c->tex[k].data, (unsigned) c->lastUsedFrame);
        }
    }
    logInfo("[texcheck] f%u: %u textures checked, %u changed, %.1f MB resident, %.1f MB of palette copies\n", (unsigned) r->frame, (unsigned) checked,
            (unsigned) bad, (double) cache->residentBytes / (1024.0 * 1024.0), (double) r->palBytes / (1024.0 * 1024.0));
}

