    // Row 0 is NDC y = +1, or -1 for GUI projections (see setProjectionFromEngine).
    *outX = (float) vp->x + (nx + 1.0f) * 0.5f * (float) vp->w;
    *outY = (float) vp->y + (r->hostPass ? ny + 1.0f : 1.0f - ny) * 0.5f * (float) vp->h;
