// Onto the pixel grid, if upright: a rotated quad matches no grid. Text and
// recorded surfaces place their quads as a whole instead (gridHold). Moving
// at most a pixel left or up, no quad out of view comes into it. The first
// corner stands for the quad: a mirrored sprite's is its right edge, on the
// same parity as its left one when it is in 2x pixels. The moved quad goes
// in gx/gy; false if it stays where it is.
static inline bool gridSnapQuad(CtrRenderer* r, const float* px, const float* py, float sw, float sh, float* gx, float* gy) {
    if (r->gridHold != 0 || !gridActive(r) || !quadUpright(px, py)) return false;
    float dx, dy;
    int32_t qx, qy;
    if (gridItemParity(r, px, py, sw, sh, &qx, &qy)) {
        dx = -gridExcessTo(r->gridMap.kx * px[0] + r->gridMap.ox, qx) * r->gridMap.invKx;
        dy = -gridExcessTo(r->gridMap.ky * py[0] + r->gridMap.oy, qy) * r->gridMap.invKy;
        if ((floatBits(dx) | floatBits(dy)) << 1 == 0) return false;
    } else {
        gridDelta(r, px[0], py[0], &dx, &dy);
        // Quads already on it (dx and dy +-0) are drawn as they are.
        if ((floatBits(dx) | floatBits(dy)) << 1 == 0 || (r->gridMap.x && !gridDoubled((px[1] - px[0]) * r->gridMap.kx, sw)) ||
            (r->gridMap.y && !gridDoubled((py[2] - py[0]) * r->gridMap.ky, sh))) {
            return false;
        }
    }
    gx[0] = px[0] + dx, gx[1] = px[1] + dx, gx[2] = px[2] + dx, gx[3] = px[3] + dx;
    gy[0] = py[0] + dy, gy[1] = py[1] + dy, gy[2] = py[2] + dy, gy[3] = py[3] + dy;
    return true;
}

