// The part of tile (tx, ty) that the page region [sx0, sx1) x [sy0, sy1)
// (w x h, which may run backwards; minX..maxY its bounds) covers: s gets its
// fractions s0, t0, s1, t1 along the region and uv its texture coordinates
// u0, v0, u1, v1 on the tileW x tileH tile. False if it covers none.
static inline bool regionTilePart(float sx0, float sy0, float w, float h, float minX, float minY, float maxX, float maxY, float tileW, float tileH,
                                  int32_t tx, int32_t ty, float* s, float* uv) {
    float cx0 = (float) tx * tileW, cx1 = cx0 + tileW;
    float cy0 = (float) ty * tileH, cy1 = cy0 + tileH;
    if (cx0 < minX) cx0 = minX;
    if (cx1 > maxX) cx1 = maxX;
    if (cy0 < minY) cy0 = minY;
    if (cy1 > maxY) cy1 = maxY;
    if (cx0 >= cx1 || cy0 >= cy1) return false;
    s[0] = (cx0 - sx0) / w, s[2] = (cx1 - sx0) / w;
    s[1] = (cy0 - sy0) / h, s[3] = (cy1 - sy0) / h;
    float ox = (float) tx * tileW;
    float oy = (float) ty * tileH;
    uv[0] = (sx0 + s[0] * w - ox) / tileW, uv[2] = (sx0 + s[2] * w - ox) / tileW;
    uv[1] = (sy0 + s[1] * h - oy) / tileH, uv[3] = (sy0 + s[3] * h - oy) / tileH;
    return true;
}

// Whether drawing page region [sx0, sx1) x [sy0, sy1) of data page pageId onto
// the quad px/py keeps the bound surface a pattern (CtrPattern): it is one,
// and this draw puts the same region, with the same alpha cut and nothing
// else that could make a clear texel less than clear, at 1:1 on a cell of the
// same grid not drawn yet. Notes the cell if so; the caller then marks the
// pattern current once the draw is made.
static bool patternAdd(CtrRenderer* r, int32_t pageId, float sx0, float sy0, float sx1, float sy1, const float* px, const float* py) {
    CtrSurface* s = &r->surfaces[r->boundSurface];
    CtrPattern* p = &s->pattern;
    if (p->version != s->version) return false;
    bool linear = r->filterOverride != 0 ? r->filterOverride == FILTER_LINEAR : r->base.texFilter;
    if (s->shift != 0 || s->windowed || linear || r->palKind != PAL_NONE) return false;
    // A replayed quad's own cut (recorded surfaces made textures draw theirs
    // so), the shader's, or the larger: alpha up to either ends clear.
    uint8_t cut = r->opAlphaCut == ALPHA_CUT_ANY ? 0 : r->opAlphaCut;
    // shd_tower has no stages outside drawTowerStrips' strips, which
    // materialize recorded layers before setting them (towerStrips).
    if (r->shaderFx != SHADER_FX_NONE && !r->fxSuspended && !(r->shaderFx == SHADER_FX_TOWER && !r->towerStrips)) {
        if (r->shaderFx != SHADER_FX_DEPTHMAP) return false;
        uint8_t fxCut = depthmapCut(r);
        cut = fxCut > cut ? fxCut : cut;
    }
    if (!quadUpright(px, py)) return false;
    float X0, Y0, X1, Y1, cornerX, cornerY;
    worldToPixel(r, px[0], py[0], &X0, &Y0);
    worldToPixel(r, px[2], py[2], &X1, &Y1);
    worldToPixel(r, px[1], py[1], &cornerX, &cornerY);
    int32_t x0 = (int32_t) lroundf(X0), y0 = (int32_t) lroundf(Y0), sx = (int32_t) sx0, sy = (int32_t) sy0;
    int32_t w = (int32_t) sx1 - sx, h = (int32_t) sy1 - sy;
    if ((float) sx != sx0 || (float) sy != sy0 || (float) (sx + w) != sx1 || (float) (sy + h) != sy1 || 0 >= w || 0 >= h) return false;
    const float e = 1.0f / 64.0f;
    if (fabsf(X0 - (float) x0) > e || fabsf(Y0 - (float) y0) > e || fabsf(X1 - (float) (x0 + w)) > e || fabsf(Y1 - (float) (y0 + h)) > e ||
        fabsf(cornerX - X1) > e || fabsf(cornerY - Y0) > e) {
        return false;
    }
    if (0 > p->pageId) {
        p->pageId = pageId;
        p->sx = sx;
        p->sy = sy;
        p->w = w;
        p->h = h;
        p->cut = cut;
        p->ox = x0 % w;
        p->oy = y0 % h;
        if (p->ox > 0) p->ox -= w;
        if (p->oy > 0) p->oy -= h;
    } else if (p->pageId != pageId || p->sx != sx || p->sy != sy || p->w != w || p->h != h || p->cut != cut) {
        return false;
    }
    int32_t dx = x0 - p->ox, dy = y0 - p->oy;
    if (0 > dx || 0 > dy || dx % w != 0 || dy % h != 0 || dx / w >= 8 || dy / h >= 8) return false;
    uint64_t bit = (uint64_t) 1 << (dy / h * 8 + dx / w);
    if ((p->cells & bit) != 0) return false;
    p->cells |= bit;
    return true;
}

