// A colour of the corners c (top left, top right, bottom right, bottom left)
// at (fx, fy) across the quad, premultiplied by its alpha, times weight w.
static CtrColor nativeCornerColor(const CtrColor* c, float fx, float fy, float w, bool straight) {
    float k[4] = { (1.0f - fx) * (1.0f - fy), fx * (1.0f - fy), fx * fy, (1.0f - fx) * fy };
    float rr = 0.0f, gg = 0.0f, bb = 0.0f, aa = 0.0f;
    for (int32_t i = 0; 4 > i; i++) {
        float a = (float) c[i].a * k[i];
        float m = straight ? k[i] : a / 255.0f;
        rr += (float) c[i].r * m;
        gg += (float) c[i].g * m;
        bb += (float) c[i].b * m;
        aa += a;
    }
    // Straight: the weight goes on alpha alone (the blend multiplies the
    // colour by it); premultiplied: on all four.
    float s = straight ? 1.0f : w;
    return (CtrColor) { (uint8_t) (rr * s + 0.5f), (uint8_t) (gg * s + 0.5f), (uint8_t) (bb * s + 0.5f), (uint8_t) (aa * w + 0.5f) };
}

