// Frees copy's texture k, made by palAllocTex but not yet drawn with.
static void palFreeTex(CtrRenderer* r, CtrPalCopy* copy, int32_t k) {
    uint32_t bytes = copy->tex[k].size;
    C3D_TexDelete(&copy->tex[k]);
    copy->has[k] = false;
    CtrTextures_returnBudget(&r->textures, bytes);
    r->palBytes -= bytes;
    copy->bytes -= bytes;
}

// Makes copy's missing x (wantX) and y (wantY) copies of tile texture src,
// or with mix from 0 to 255 (and wantX alone), the two mixed at that weight.
// Makes neither if both are wanted and one doesn't fit: an x copy kept
// while its y didn't fit would hold whatever its memory held before, and
// the retry, which makes only what is missing, would never recolour it.
static bool palMakeCopies(CtrRenderer* r, CtrPalCopy* copy, const C3D_Tex* src, bool wantX, bool wantY, int32_t mix) {
    const CtrPalTable* t = r->palTable;
    // A tile's colours that no row matches stay as they are, which only an
    // RGBA5551 tile's are sure to fit RGBA5551.
    GPU_TEXCOLOR fmt = src->fmt == GPU_RGBA5551 && t->exact && 0 > mix ? GPU_RGBA5551 : GPU_RGBA8;
    C3D_Tex* dx = nullptr;
    C3D_Tex* dy = nullptr;
    bool probe = r->textures.probeHashes;
    if (wantX) {
        if (!palAllocTex(r, copy, &copy->tex[0], fmt)) {
            if (probe) logInfo("[palprobe] f%u pal %d/%d: x copy didn't fit\n", (unsigned) r->frame, (int) copy->pageId, (int) copy->tile);
            return false;
        }
        dx = &copy->tex[0];
        copy->has[0] = true;
    }
    if (wantY) {
        if (!palAllocTex(r, copy, &copy->tex[1], fmt)) {
            if (probe) {
                logInfo("[palprobe] f%u pal %d/%d: y copy didn't fit%s\n", (unsigned) r->frame, (int) copy->pageId, (int) copy->tile,
                        dx != nullptr ? (PAL_PROBE_KEEP_X ? ", x copy kept unmade" : ", x copy freed") : "");
            }
            if (dx != nullptr && !PAL_PROBE_KEEP_X) palFreeTex(r, copy, 0);
            return false;
        }
        dy = &copy->tex[1];
        copy->has[1] = true;
    }
    if (0 <= mix) {
        copy->mixed = true;
        copy->mixW = (uint8_t) mix;
        copy->mixFrame = r->frame;
    }
    uint64_t start = svcGetSystemTick();
    palRecolourTile(t, copy, src, dx, dy, mix);
    if (dx != nullptr) flushDataCache(r, dx->data, dx->size);
    if (dy != nullptr) flushDataCache(r, dy->data, dy->size);
    if (probe) {
        if (dx != nullptr) copy->probeHash[0] = CtrTextures_hashTexels(dx);
        if (dy != nullptr) copy->probeHash[1] = CtrTextures_hashTexels(dy);
        logInfo("[palprobe] f%u pal %d/%d: recoloured%s%s %dx%d at %d,%d; x %s %08x, y %s %08x\n", (unsigned) r->frame, (int) copy->pageId, (int) copy->tile,
                dx != nullptr ? " x" : "", dy != nullptr ? " y" : "", (int) copy->w, (int) copy->h, (int) copy->x, (int) copy->y,
                copy->has[0] ? (dx != nullptr ? "now" : "before") : "none", (unsigned) (copy->has[0] ? CtrTextures_hashTexels(&copy->tex[0]) : 0),
                copy->has[1] ? (dy != nullptr ? "now" : "before") : "none", (unsigned) (copy->has[1] ? CtrTextures_hashTexels(&copy->tex[1]) : 0));
    }
    uint64_t ticks = svcGetSystemTick() - start;
    r->palFrameTicks += ticks;
    r->palFrameTexels += (uint32_t) copy->w * (uint32_t) copy->h;
    r->palFrameCopies++;
    r->palStats.tiles++;
    r->palStats.ticks += ticks;
    r->palStats.texels += (uint64_t) copy->w * (uint64_t) copy->h;
    if (16 >= r->palStats.tiles || (r->palStats.tiles & 63u) == 0) {
        logInfo("Renderer: palette shader recoloured %dx%d at %d,%d of tile %d of page %d (%s%s) in %.2f ms; %u copies, %.1f Mtexels in %.0f ms, %.1f MB held\n",
                (int) copy->w, (int) copy->h, (int) copy->x, (int) copy->y, (int) copy->tile, (int) copy->pageId, 0 <= mix ? "mixed" : (wantX ? "x" : ""), wantY ? "y" : "",
                (double) ticks * 1000.0 / (double) SYSCLOCK_ARM11, (unsigned) r->palStats.tiles, (double) r->palStats.texels / 1e6,
                (double) r->palStats.ticks * 1000.0 / (double) SYSCLOCK_ARM11, (double) r->palBytes / (1024.0 * 1024.0));
    }
    return true;
}

// The part of a side of `size` texels that a copy holding [lo, hi) covers:
// from *at, *len texels, a power of two of at least 8, on 8-texel blocks.
static void palCropSide(int32_t lo, int32_t hi, int32_t size, int16_t* at, int16_t* len) {
    lo &= ~7;
    int32_t n = 8;
    while (hi - lo > n) n *= 2;
    if (n >= size) {
        *at = 0;
        *len = (int16_t) size;
        return;
    }
    if (lo + n > size) lo = size - n;
    *at = (int16_t) lo;
    *len = (int16_t) n;
}

// Whether remaking a copy is put off to a later frame: its old one is drawn
