// Only physical window x may be cut at a fractional pixel. For portrait
// targets that is logical y; never apply this to physical y (row 0 of a
// 1024-row target can hang the GPU when cut there).
static bool cutSurfaceQuadToGpuEdge(const CtrSurface* dst, float x0, float y0, float* x1, float* y1,
                                    float u0, float v0, float* u1, float* v1) {
    float scale = (float) (1 << dst->shift);
    if (!dst->windowed) return cutQuadToGpuEdge(x0, x1, u0, u1, scale);
    float end = *y1 - (float) dst->winY;
    bool shows = cutQuadToGpuEdge(y0 - (float) dst->winY, &end, v0, v1, scale);
    *y1 = end + (float) dst->winY;
    return shows;
}

static void ctrApplyProjection(Renderer* renderer, const Matrix4f* viewMatrix, const Matrix4f* projectionMatrix) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    RENDER_TIMED(r, TIME_TARGETS);
    Renderer_applyProjection(renderer, viewMatrix, projectionMatrix);
    setProjectionFromEngine(r);
}

static void ctrSetMatrix(Renderer* renderer, int32_t matrixType, Matrix4f matrix) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    RENDER_TIMED(r, TIME_TARGETS);
    if (0 > matrixType || matrixType >= MATRICES_MAX) return;
    if (memcmp(&renderer->gmlMatrices[matrixType], &matrix, sizeof(Matrix4f)) == 0) return;
    renderer->gmlMatrices[matrixType] = matrix;
    Matrix4f worldView;
    Matrix4f_multiply(&worldView, &renderer->gmlMatrices[MATRIX_VIEW], &renderer->gmlMatrices[MATRIX_WORLD]);
    Matrix4f worldViewProjection;
    Matrix4f_multiply(&worldViewProjection, &renderer->gmlMatrices[MATRIX_PROJECTION], &worldView);
    renderer->gmlMatrices[MATRIX_WORLD_VIEW] = worldView;
    renderer->gmlMatrices[MATRIX_WORLD_VIEW_PROJECTION] = worldViewProjection;
    setProjectionFromEngine(r);
}

