static void saveState(CtrRenderer* r, CtrTargetState* st) {
    st->viewport = r->viewport;
    st->scissorEnabled = r->scissorEnabled;
    st->scissor = r->scissor;
    st->hostPass = r->hostPass;
    memcpy(st->gmlMatrices, r->base.gmlMatrices, sizeof(st->gmlMatrices));
    st->cameraCurrent = r->base.cameraCurrent;
    st->portX = r->base.CPortX;
    st->portY = r->base.CPortY;
    st->portW = r->base.CPortW;
    st->portH = r->base.CPortH;
}

static void restoreState(CtrRenderer* r, const CtrTargetState* st) {
    flushBatch(r);
    r->viewport = st->viewport;
    r->scissorEnabled = st->scissorEnabled;
    r->scissor = st->scissor;
    r->hostPass = st->hostPass;
    memcpy(r->base.gmlMatrices, st->gmlMatrices, sizeof(st->gmlMatrices));
    r->base.cameraCurrent = st->cameraCurrent;
    r->base.CPortX = st->portX;
    r->base.CPortY = st->portY;
    r->base.CPortW = st->portW;
    r->base.CPortH = st->portH;
    if (r->inFrame && r->boundTarget != nullptr) applyViewport(r);
    setProjectionFromEngine(r);
}

