static int32_t allocSurfaceSlot(CtrRenderer* r) {
    for (uint32_t i = 0; r->surfaceCount > i; i++) {
        if (!r->surfaces[i].used && !r->surfaces[i].reserved) return (int32_t) i;
    }
    // The open batch may point at a surface's C3D_Tex, which is about to move.
    flushBatch(r);
    r->surfaces = safeRealloc(r->surfaces, (r->surfaceCount + 1) * sizeof(CtrSurface));
    memset(&r->surfaces[r->surfaceCount], 0, sizeof(CtrSurface));
    return (int32_t) r->surfaceCount++;
}

// Rows kept past a surface's last one (rounded up to the 8-row tiles): what
// linear filtering at its bottom edge reaches, as before (cleared pixels).
#define SURFACE_GUARD_ROWS 8

// How many of a surface texture's rows are stored. The PICA200 samples
// power-of-two textures, but a surface's pixels are only its texture's first
// rows (row 0 is memory row 0), so the rest isn't allocated: a 360x360
// surface stores 512x368 texels, 736 KB instead of 1 MB. DELTARUNE Chapter
// 5's Flowery fight keeps two dozen of them in linear memory, and the 7 MB
// saved is what its textures were short of. A render target over such a
// texture is only that many rows tall, so nothing is drawn or cleared past
// them; sampling only reads past them for coordinates outside the surface.
static int32_t surfaceRows(int32_t height, int32_t texH) {
    int32_t rows = ((height + 7) & ~7) + SURFACE_GUARD_ROWS;
    return rows < texH ? rows : texH;
}

// An RGBA8 texW x texH texture storing only its first `rows` rows.
// citro3d's C3D_TexInit only makes whole textures, so this sets it up the
// same way with a smaller allocation; C3D_TexDelete frees either.
static bool initSurfaceTex(C3D_Tex* tex, int32_t texW, int32_t texH, int32_t rows, bool vram) {
    if (rows >= texH) {
        if (!(vram ? C3D_TexInitVRAM(tex, (u16) texW, (u16) texH, GPU_RGBA8) : C3D_TexInit(tex, (u16) texW, (u16) texH, GPU_RGBA8))) return false;
    } else {
        size_t size = (size_t) texW * (size_t) rows * 4u;
        void* data = vram ? vramAlloc(size) : linearAlloc(size);
        if (data == nullptr) return false;
        memset(tex, 0, sizeof(*tex));
        tex->data = data;
        tex->fmt = GPU_RGBA8;
        tex->size = size;
        tex->width = (u16) texW;
        tex->height = (u16) texH;
        tex->param = GPU_TEXTURE_MODE(GPU_TEX_2D);
    }
    C3D_TexSetWrap(tex, GPU_CLAMP_TO_EDGE, GPU_CLAMP_TO_EDGE);
    return true;
}

static bool tryVramTarget(C3D_Tex* tex, C3D_RenderTarget** target, int32_t texW, int32_t texH, int32_t rows) {
    if (!initSurfaceTex(tex, texW, texH, rows, true)) return false;
    *target = C3D_RenderTargetCreateFromTex(tex, GPU_TEXFACE_2D, 0, -1);
    if (*target != nullptr) {
        // The buffer's rows are memory rows; the viewport is placed from its
        // far end (applyEyeViewport), so the surface keeps rows 0 onwards.
        (*target)->frameBuf.height = (u16) textureRows(tex);
        return true;
    }
    C3D_TexDelete(tex);
    return false;
}

static bool yieldMirrors(CtrRenderer* r, size_t need);

// A VRAM texture with a render target over its stored rows, or false if
// VRAM is short, even without tiles' copies in it (see "Tiles in VRAM").
static bool initVramTarget(CtrRenderer* r, C3D_Tex* tex, C3D_RenderTarget** target, int32_t texW, int32_t texH, int32_t rows) {
    if (tryVramTarget(tex, target, texW, texH, rows)) return true;
    while (yieldMirrors(r, (size_t) texW * (size_t) rows * 4u)) {
        if (tryVramTarget(tex, target, texW, texH, rows)) return true;
    }
    return false;
}

// Texture tiles fill linear memory up to their budget, which leaves little
// for surfaces VRAM has no room for: when it is short, the tiles used least
// recently make way (they load again when drawn). DELTARUNE Chapter 3's
// Roaring Knight keeps four 640x480 surfaces in its last phase; recorded
// instead, each of the 480 strips it draws one of them in replayed all its
// draws, at 3 frames per second.
//
// Only so far, though (SURFACE_EVICT_LIMIT): the fight also makes a 640x480
// afterimage of the screen every few frames, each kept for twenty, and with
// all of those in linear memory the tiles the scene draws no longer fit, so
// they loaded from the SD card again every few frames, for a second each.
// The afterimages past the limit are recorded instead (and don't show). A
// spare texture from a surface freed lately is used first.
//
// Tiles not drawn in the last SURFACE_HOT_TILE_FRAMES go first, then those
// drawn lately, except the current frame's. Linear memory gets fragmented,
// though, and freeing every tile but the current frame's may still leave no
// block big enough: on the Old 3DS the Knight's finale has 7 MB free in
// pieces, so each afterimage (one every three frames) evicted the scene's
// tiles for nothing, failed and was recorded, and the tiles loaded again
// (373 loads and 453 evictions in 20 s). Once that happens, for
// SURFACE_HOT_EVICT_PAUSE_FRAMES only idle tiles make way for surface
// textures, and a surface they can't make room for is recorded at once.
static uint32_t linearSurfaceBytes(CtrRenderer* r) {
    uint32_t bytes = 0;
    for (uint32_t i = 0; r->surfaceCount > i; i++) {
        if (r->surfaces[i].used && r->surfaces[i].spilled && r->surfaces[i].tex.data != nullptr) bytes += r->surfaces[i].tex.size;
    }
    for (ptrdiff_t i = 0; arrlen(r->spareTextures) > i; i++) bytes += r->spareTextures[i].tex.size;
    return bytes;
}

static bool initLinearTexture(CtrRenderer* r, C3D_Tex* tex, int32_t texW, int32_t texH, int32_t rows) {
    for (ptrdiff_t i = arrlen(r->spareTextures) - 1; i >= 0; i--) {
        const C3D_Tex* spare = &r->spareTextures[i].tex;
        if (spare->width != texW || spare->height != texH || textureRows(spare) != rows) continue;
        *tex = r->spareTextures[i].tex;
        arrdel(r->spareTextures, i);
        return true;
    }
    bool evicted = false, evictedHot = false;
    while (!initSurfaceTex(tex, texW, texH, rows, false)) {
        if (arrlen(r->spareTextures) > 0) {
            C3D_TexDelete(&r->spareTextures[0].tex);
            arrdel(r->spareTextures, 0);
            continue;
        }
        if (!r->liveSnapshot && linearSurfaceBytes(r) + (uint32_t) (texW * rows * 4) > SURFACE_EVICT_LIMIT) return false;
        if (CtrTextures_evictOldestIdle(&r->textures, SURFACE_HOT_TILE_FRAMES)) {
            evicted = true;
            continue;
        }
        if ((r->liveSnapshot || r->frame >= r->hotEvictFrame) && CtrTextures_evictOldest(&r->textures)) {
            evicted = evictedHot = true;
            continue;
        }
        if (evictedHot && !r->liveSnapshot) {
            r->hotEvictFrame = r->frame + SURFACE_HOT_EVICT_PAUSE_FRAMES;
            logInfo("Renderer: evicting the tiles drawn lately left no room for a %dx%d surface texture (%.1f MB linear free, in pieces); "
                    "for %u frames only idle tiles make way for surface textures\n",
                    texW, texH, (double) linearSpaceFree() / (1024.0 * 1024.0), (unsigned) SURFACE_HOT_EVICT_PAUSE_FRAMES);
        }
        return false;
    }
    if (evicted) {
        logInfo("Renderer: evicted texture tiles for a %dx%d surface texture (%.1f MB linear free)\n", texW, texH,
                (double) linearSpaceFree() / (1024.0 * 1024.0));
    }
    return true;
}

