// Restoring retained pixels, or replacing replay before an unsupported blend,
// must not use speculative surfaces' eviction limit or hot-eviction pause.
// Submit every queued user before evicting even this frame's texture tiles.
static bool initRequiredLinearTexture(CtrRenderer* r, C3D_Tex* tex, int32_t texW, int32_t texH, int32_t rows, uint32_t* evicted) {
    *evicted = 0;
    bool ok = initLinearTextureForCpu(r, tex, texW, texH, rows);
    while (!ok && CtrTextures_evictOldest(&r->textures)) ok = initSurfaceTex(tex, texW, texH, rows, false);
    if (!ok) {
        if (r->inFrame) {
            flushBatch(r);
            runFrameSoFar(r);
        } else {
            CtrGpu_waitIdle();
        }
        while (!ok && CtrTextures_evictLeastRecent(&r->textures)) {
            (*evicted)++;
            ok = initSurfaceTex(tex, texW, texH, rows, false);
        }
    }
    return ok;
}

