// Prepares a surface for sampling and returns its texture.
static C3D_Tex* surfaceTexture(CtrRenderer* r, int32_t surfaceId) {
    CtrSurface* s = getSurface(r, surfaceId);
    if (s != nullptr && s->skipRec != nullptr) {
        LOG_ONCE("Renderer: draws recorded on surface %d drawn late, when sampled\n", (int) surfaceId);
        r->skip.lateSyncs++;
        skipSync(r, surfaceId);
        s = getSurface(r, surfaceId);
    }
    if (s == nullptr || s->recorded || !touchSurface(r, s)) return nullptr;
    if (s->lazy != nullptr) {
        // It shows after all.
        s->seenFrame = r->frame;
        flushLazy(r, surfaceId);
    }
    if (s->needsClear && r->inFrame) {
        // Never drawn to: give it defined (transparent) contents first.
        int32_t previous = r->boundSurface;
        C3D_RenderTarget* previousTarget = r->boundTarget;
        bindSurface(r, surfaceId);
        if (previousTarget != nullptr) {
            if (0 <= previous) bindTarget(r, previousTarget, previous);
            else bindTarget(r, previousTarget, -1);
        }
    }
    if (s->drawnSinceSplit && r->boundSurface != surfaceId) splitFrame(r);
    if (s->spilled) {
        CtrScratch* sc = &r->scratches[s->scratch];
        if (sc->pendingStore && sc->owner == surfaceId) {
            // Its newest pixels are still in the scratch (storeSpill), a
            // texture of the same size: sampled there, from VRAM, they
            // needn't be copied out first. A scratch storing more rows
            // would differ below the surface's own, so that one is copied.
            bool same = sc->tex.width == s->tex.width && sc->tex.height == s->tex.height && textureRows(&sc->tex) == textureRows(&s->tex);
            if (sc->target != nullptr && same) {
#ifdef CTRPORT_RENDER_TIMING
                r->timing.scratchSamples++;
#endif
                sc->sampled = true;
                return &sc->tex;
            }
            flushPendingStore(r, s->scratch);
        }
        s->storeQueued = false; // read since
    }
    return &s->tex;
}

