static void deleteTarget(C3D_RenderTarget** target) {
    if (*target == nullptr) return;
    C3D_RenderTargetDelete(*target);
    *target = nullptr;
}

// A screen render target linked to its framebuffer, or nullptr if VRAM is
// short. width is the screen width (the buffer is portrait).
static C3D_RenderTarget* createScreenTarget(int32_t width, gfxScreen_t screen, gfx3dSide_t side, u32 transferFlags) {
    C3D_RenderTarget* target = C3D_RenderTargetCreate(TOP_SCREEN_H, width, GPU_RB_RGBA8, -1);
    if (target == nullptr) {
        logWarn("Renderer: no VRAM for a %dx240 screen target (%.0f KB free)\n", (int) width, (double) vramSpaceFree() / 1024.0);
        return nullptr;
    }
    C3D_RenderTargetSetOutput(target, screen, side, transferFlags);
    return target;
}

