    u8* shown = CtrPacer_shownFramebuffer(screen, GFX_LEFT, &w, &h);
    u8* back = CtrPacer_backFramebuffer(screen, GFX_LEFT);
    if (carried == nullptr || shown == nullptr || back == nullptr || shown == back || (carried != shown && carried != back)) {
        return false;
    }
    u32 bytes = (u32) w * h * 3u;
    if (screen == GFX_TOP) {
        memset(carried, 0, SCREENS_CARRY_AT);
        memset(carried + SCREENS_CARRY_AT + SCREENS_CARRY_BYTES, 0, bytes - SCREENS_CARRY_AT - SCREENS_CARRY_BYTES);
    }
    u8* copy = carried == shown ? back : shown;
    memcpy(copy, carried, bytes);
    GSPGPU_FlushDataCache(carried, bytes);
    GSPGPU_FlushDataCache(copy, bytes);
    return true;
