    float sag = 0.25f / big;
    int32_t segments = 1.0f > sag ? (int32_t) ceilf((float) M_PI / acosf(1.0f - sag)) : 8;
    segments = segments < 8 ? 8 : (segments > 256 ? 256 : segments);
