typedef struct {
    C3D_Tex* tex;
    float scaleU, offsetU, scaleV, offsetV; // page/surface UV -> tile UV
    bool portrait;
} CtrTexRef;

// Resolves a texture handle. Sprite UVs arrive normalized to the whole
// texture page; for tiled pages they are remapped into the tile that holds
// the sprite, so a primitive can't span tiles.
static bool resolveTextureHandle(CtrRenderer* r, uint32_t handle, CtrTexRef* out) {
    out->tex = &r->white;
    out->scaleU = out->scaleV = 1.0f;
    out->offsetU = out->offsetV = 0.0f;
    out->portrait = false;
    if (handle == 0) return false;
    if (handle & SURFACE_TEXTURE_FLAG) {
        int32_t sid = (int32_t) (handle & ~SURFACE_TEXTURE_FLAG);
        C3D_Tex* tex = surfaceTexture(r, sid);
        if (tex == nullptr) return false;
        CtrSurface* s = &r->surfaces[sid];
        out->tex = tex;
        out->scaleU = (float) s->width / (float) (tex->width << s->shift);
        out->scaleV = (float) s->height / (float) (tex->height << s->shift);
        if (s->windowed) {
            out->portrait = true;
            out->scaleU = (float) s->height / (float) tex->width;
            out->scaleV = (float) s->width / (float) tex->height;
            out->offsetU = -(float) s->winY / (float) tex->width;
            out->offsetV = -(float) s->winX / (float) tex->height;
        }
        return true;
    }
    TexturePageItem* tpag;
    CtrPage* page = acquireTpagPage(r, (int32_t) handle - 1, &tpag);
    if (page == nullptr) return false;
    CtrSurface* mapped = recordedPageSurface(r, page);
    if (mapped != nullptr && mapped->windowed) {
        out->tex = surfaceTexture(r, (int32_t) (mapped - r->surfaces));
        if (out->tex == nullptr) return false;
        out->portrait = true;
        out->scaleU = (float) page->height / (float) out->tex->width;
        out->scaleV = (float) page->width / (float) out->tex->height;
        out->offsetU = -(float) mapped->winY / (float) out->tex->width;
        out->offsetV = -(float) mapped->winX / (float) out->tex->height;
        return true;
    }
    if (mapped != nullptr) {
        OOMPORT_LOG_ONCE(primitiveSurface, "Renderer: a sprite of a surface larger than %d pixels can't texture a primitive\n", MAX_SURFACE_SIZE);
        return false;
    }
    int32_t tx = tpag->sourceX / page->tileW;
    int32_t ty = tpag->sourceY / page->tileH;
    if (tx >= page->tilesX) tx = page->tilesX - 1;
    if (ty >= page->tilesY) ty = page->tilesY - 1;
    CtrTextures_ensureTiles(&r->textures, page, tx, ty, tx, ty);
    CtrTile* tile = &page->tiles[ty * page->tilesX + tx];
    if (!tile->valid && page->formatsKnown && tile->format == CTR_TILE_EMPTY) {
        out->tex = &r->textures.clear;
        return true;
    }
    if (!tile->valid) return false;
    if ((tpag->sourceX + tpag->sourceWidth - 1) / page->tileW != tx || (tpag->sourceY + tpag->sourceHeight - 1) / page->tileH != ty) {
        OOMPORT_LOG_ONCE(primitiveTiles, "Renderer: primitive texture %u spans texture tiles; drawing part of it\n", handle);
    }
    out->tex = CtrTextures_drawTex(tile);
    out->scaleU = (float) page->width / (float) page->tileW;
    out->scaleV = (float) page->height / (float) page->tileH;
    out->offsetU = -(float) tx;
    out->offsetV = -(float) ty;
    return true;
}

static void pushPrimitiveVertex(CtrRenderer* r, CtrVertex* dst, const CtrVertex* src, const CtrTexRef* ref) {
    *dst = *src;
    if (drawingBothEyes(r)) dst->z = r->vertexZ;
    // The multi-texture program reads a unit from z beyond +-32 (and NaN).
    if (!(MULTI_PLAIN_Z > fabsf(dst->z))) r->batchPlainOnly = true;
    dst->u = (ref->portrait ? src->v : src->u) * ref->scaleU + ref->offsetU;
    dst->v = (ref->portrait ? src->u : src->v) * ref->scaleV + ref->offsetV;
}

static void emitPrimitiveLine(CtrRenderer* r, const CtrVertex* a, const CtrVertex* b, const CtrTexRef* ref) {
    float dx = b->x - a->x;
    float dy = b->y - a->y;
    float len = sqrtf(dx * dx + dy * dy);
    if (0.0001f > len) return;
    float nx = (-dy / len) * 0.5f;
    float ny = (dx / len) * 0.5f;
    CtrVertex* v = reserveVertices(r, ref->tex, 6);
    if (v == nullptr) return;
    CtrVertex q[4] = { *a, *a, *b, *b };
    q[0].x += nx; q[0].y += ny;
    q[1].x -= nx; q[1].y -= ny;
    q[2].x -= nx; q[2].y -= ny;
    q[3].x += nx; q[3].y += ny;
    const int order[6] = { 0, 1, 2, 0, 2, 3 };
    for (int i = 0; 6 > i; i++) pushPrimitiveVertex(r, &v[i], &q[order[i]], ref);
}

// Converts any primitive type to the triangle list the batch uses.
static void submitPrimitive(CtrRenderer* r, int32_t type, const CtrVertex* src, int32_t count, uint32_t textureHandle) {
    if (0 >= count) return;
    CtrTexRef ref;
    resolveTextureHandle(r, textureHandle, &ref);
    switch (type) {
        case PRIMITIVE_TRIANGLES: {
            int32_t n = count - count % 3;
            CtrVertex* v = reserveVertices(r, ref.tex, (uint32_t) n);
            if (v == nullptr) return;
            for (int32_t i = 0; n > i; i++) pushPrimitiveVertex(r, &v[i], &src[i], &ref);
            break;
        }
        case PRIMITIVE_TRIANGLE_STRIP:
        case PRIMITIVE_TRIANGLE_FAN: {
            if (3 > count) return;
            CtrVertex* v = reserveVertices(r, ref.tex, (uint32_t) (count - 2) * 3);
            if (v == nullptr) return;
            for (int32_t i = 2; count > i; i++) {
                const CtrVertex* a = type == PRIMITIVE_TRIANGLE_FAN ? &src[0] : &src[i - 2];
                pushPrimitiveVertex(r, v++, a, &ref);
                pushPrimitiveVertex(r, v++, &src[i - 1], &ref);
                pushPrimitiveVertex(r, v++, &src[i], &ref);
            }
            break;
        }
        case PRIMITIVE_LINES:
            for (int32_t i = 0; count > i + 1; i += 2) emitPrimitiveLine(r, &src[i], &src[i + 1], &ref);
            break;
        case PRIMITIVE_LINE_STRIP:
            for (int32_t i = 0; count > i + 1; i++) emitPrimitiveLine(r, &src[i], &src[i + 1], &ref);
            break;
        case PRIMITIVE_POINTS:
            for (int32_t i = 0; count > i; i++) {
                CtrVertex* v = reserveVertices(r, ref.tex, 6);
                if (v == nullptr) return;
                CtrVertex q[4] = { src[i], src[i], src[i], src[i] };
                q[1].x += 1.0f;
                q[2].x += 1.0f;
                q[2].y += 1.0f;
                q[3].y += 1.0f;
                const int order[6] = { 0, 1, 2, 0, 2, 3 };
                for (int k = 0; 6 > k; k++) pushPrimitiveVertex(r, &v[k], &q[order[k]], &ref);
            }
            break;
        default:
            break;
    }
}

// ===[ Perspective ]===
//
// sh_perspective (DELTARUNE Chapter 5's draw_sprite_pos_fixed and
// draw_surface_pos_fixed: the open TV panel in Ralsei's castle's basketball
// court, the floor textures on slopes) takes each vertex's texture
// coordinate from its normal as (qu, qv, q), interpolates those across the
// triangle and samples at (qu / q, qv / q), so a quad drawn as a trapezoid
// has its texture in perspective. The PICA interpolates u and v straight, so
// each triangle is cut into a grid of smaller ones, exact at their corners
// and fine enough that straight interpolation between them is never
// PERSPECTIVE_TOLERANCE of a texel off. The basketball panel takes 26 cuts a
// side.

#define PERSPECTIVE_TOLERANCE (1.0f / 64.0f)
#define PERSPECTIVE_MAX_CUTS 32

static void perspectiveUv(const float* stq, float* u, float* v) {
    if (stq[2] == 0.0f) {
        *u = *v = 0.0f;
        return;
    }
    *u = stq[0] / stq[2];
    *v = stq[1] / stq[2];
}

// Along an edge from s to t, a coordinate is (A + Bx) / (C + Dx) for x in
// [0, 1], whose second derivative 2D(AD - BC) / (C + Dx)^3 is largest where q
// is smallest. Straight interpolation over a piece 1 / n long is off by at
// most an eighth of that over n squared.
static int32_t perspectiveCuts(const float* a, const float* b, const float* c, float texW, float texH) {
    const float* p[3] = { a, b, c };
    float worst = 0.0f;
    for (int k = 0; 3 > k; k++) {
        const float* s = p[k];
        const float* t = p[(k + 1) % 3];
        float qs = s[2], dq = t[2] - s[2];
        if (0.0f >= qs * t[2]) return PERSPECTIVE_MAX_CUTS; // q reaches 0: no texture to be exact to
        float qmin = fminf(fabsf(qs), fabsf(t[2]));
        float q3 = qmin * qmin * qmin;
        float du = fabsf(2.0f * dq * (s[0] * dq - (t[0] - s[0]) * qs)) / q3 * texW;
        float dv = fabsf(2.0f * dq * (s[1] * dq - (t[1] - s[1]) * qs)) / q3 * texH;
        worst = fmaxf(worst, fmaxf(du, dv));
    }
    float cuts = ceilf(sqrtf(worst / (8.0f * PERSPECTIVE_TOLERANCE)));
    if (!(cuts > 1.0f)) return 1;
    return PERSPECTIVE_MAX_CUTS > cuts ? (int32_t) cuts : PERSPECTIVE_MAX_CUTS;
}

// The grid's corner (i, j): i / n of the way from a to b and j / n from a to c.
static CtrVertex perspectiveVertex(const CtrVertex* const* v, const float* const* stq, float wb, float wc, bool oneColour) {
    float wa = 1.0f - wb - wc;
    CtrVertex out;
    out.x = v[0]->x * wa + v[1]->x * wb + v[2]->x * wc;
    out.y = v[0]->y * wa + v[1]->y * wb + v[2]->y * wc;
    out.z = v[0]->z * wa + v[1]->z * wb + v[2]->z * wc;
    if (oneColour) {
        out.r = v[0]->r, out.g = v[0]->g, out.b = v[0]->b, out.a = v[0]->a;
    } else {
        out.r = (uint8_t) lroundf(v[0]->r * wa + v[1]->r * wb + v[2]->r * wc);
        out.g = (uint8_t) lroundf(v[0]->g * wa + v[1]->g * wb + v[2]->g * wc);
        out.b = (uint8_t) lroundf(v[0]->b * wa + v[1]->b * wb + v[2]->b * wc);
        out.a = (uint8_t) lroundf(v[0]->a * wa + v[1]->a * wb + v[2]->a * wc);
    }
    float m[3];
    for (int k = 0; 3 > k; k++) m[k] = stq[0][k] * wa + stq[1][k] * wb + stq[2][k] * wc;
    perspectiveUv(m, &out.u, &out.v);
    return out;
}

