static void noteText(CtrRenderer* r, const char* text, float x0, float y0, float x1, float y1, bool small) {
    const C3D_Mtx* p = &r->projection;
    float flip = p->r[1].y < 0.0f ? 1.0f : -1.0f; // drawing y grows down the surface either way
    float out[4] = { 1e9f, 1e9f, -1e9f, -1e9f };
    float xs[2] = { x0, x1 }, ys[2] = { y0, y1 };
    for (int i = 0; 4 > i; i++) {
        float x = xs[i & 1], y = ys[i >> 1];
        float ndcX = p->r[0].x * x + p->r[0].y * y + p->r[0].w;
        float ndcY = p->r[1].x * x + p->r[1].y * y + p->r[1].w;
        float sx = (ndcX + 1.0f) * 0.5f * (float) r->viewport.w + (float) r->viewport.x;
        float sy = (1.0f - flip * ndcY) * 0.5f * (float) r->viewport.h + (float) r->viewport.y;
        out[0] = minF(out[0], sx);
        out[1] = minF(out[1], sy);
        out[2] = maxF(out[2], sx);
        out[3] = maxF(out[3], sy);
    }
    if (!small) return;
    mergeBox(&r->smallTextValid, r->smallText, out);
    if (smallTextAge(r, text, out) < 90) mergeBox(&r->freshTextValid, r->freshText, out);
}

