// The magnifier doesn't follow it, or it would sit on that corner. Black text
// (UNDERTALE's speech bubbles) is not dim.
static bool isDimText(int32_t c1, int32_t c2, int32_t c3, int32_t c4, float alpha) {
    if (alpha < 0.55f) return true;
    int32_t colors[4] = { c1, c2, c3, c4 };
    for (int i = 0; 4 > i; i++) {
        int32_t r = colors[i] & 0xFF, g = (colors[i] >> 8) & 0xFF, b = (colors[i] >> 16) & 0xFF;
        int32_t hi = r > g ? (r > b ? r : b) : (g > b ? g : b);
        int32_t lo = r < g ? (r < b ? r : b) : (g < b ? g : b);
        if (hi - lo > 24 || 0x40 > hi || hi > 0xC0) return false;
    }
    return true;
}

