    r->blendEnable = d->blendEnable;
    r->alphaTestEnable = d->alphaTestEnable;
    r->alphaTestRef = d->alphaTestRef;
    memcpy(r->colorWrite, d->colorWrite, sizeof(r->colorWrite));
    r->fogEnable = d->fogEnable;
    r->fogColor = d->fogColor;
    r->base.texFilter = d->texFilter;
    r->filterOverride = d->filterOverride;
    r->shaderFx = d->shaderFx;
    r->fxShader = d->fxShader;
