    ss->slot = copyId;
    ss->shift = r->surfaces[copyId].shift;

    uint32_t tpagIndex = DataWin_3dsAllocTpagSlot(dw, r->originalTpagCount);
    TexturePageItem* tpag = &dw->tpag.items[tpagIndex];
    // A copy wider or taller than the GPU allows was clamped: the sprite keeps
    // its size and the clipped edge stays transparent.
    tpag->sourceX = 0;
    tpag->sourceY = 0;
    tpag->sourceWidth = (uint16_t) r->surfaces[copyId].width;
    tpag->sourceHeight = (uint16_t) r->surfaces[copyId].height;
    tpag->targetX = 0;
    tpag->targetY = 0;
    tpag->targetWidth = tpag->sourceWidth;
    tpag->targetHeight = tpag->sourceHeight;
    tpag->boundingWidth = (uint16_t) w;
    tpag->boundingHeight = (uint16_t) h;
    tpag->texturePageId = surfaceSpritePageId(slot);
    ss->tpagIndex = (int32_t) tpagIndex;

    // DataWin_allocSpriteSlot names the slot; a reused slot keeps its name.
    uint32_t spriteIndex = DataWin_allocSpriteSlot(dw, r->originalSpriteCount);
    Sprite* sprite = &dw->sprt.sprites[spriteIndex];
    sprite->present = true;
    sprite->width = (uint32_t) w;
    sprite->height = (uint32_t) h;
    sprite->marginLeft = 0;
    sprite->marginTop = 0;
    sprite->marginRight = w - 1;
