// Only sprites made by sprite_create_from_surface can be deleted.
static void ctrDeleteSprite(Renderer* renderer, int32_t spriteIndex) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    DataWin* dw = renderer->dataWin;
    if (0 > spriteIndex || dw->sprt.count <= (uint32_t) spriteIndex || r->originalSpriteCount > (uint32_t) spriteIndex) return;
    Sprite* sprite = &dw->sprt.sprites[spriteIndex];
    if (sprite->textureCount == 0) return;
    for (int32_t slot = 0; arrlen(r->surfaceSprites) > slot; slot++) {
        if (r->surfaceSprites[slot] != nullptr && r->surfaceSprites[slot]->spriteIndex == spriteIndex) {
            freeSurfaceSprite(r, slot);
            break;
        }
    }
    // Keep the name: the slot stays in sprt.count and asset lookups read it.
    free(sprite->tpagIndices);
    const char* name = sprite->name;
    memset(sprite, 0, sizeof(Sprite));
    sprite->name = name;
}

