static uint32_t ctrSpriteGetTexture(Renderer* renderer, int32_t tpagIndex) {
    DataWin* dw = renderer->dataWin;
    if (0 > tpagIndex || dw->tpag.count <= (uint32_t) tpagIndex) return 0;
    if (0 > dw->tpag.items[tpagIndex].texturePageId) return 0;
    return (uint32_t) (tpagIndex + 1);
}

static uint32_t ctrSurfaceGetTexture(Renderer* renderer, int32_t surfaceID) {
    if (getSurface((CtrRenderer*) renderer, surfaceID) == nullptr) return 0;
    return SURFACE_TEXTURE_FLAG | (uint32_t) surfaceID;
}

// Size of the texture behind a handle, as the game sees it (whole page or surface).
static bool textureHandleSize(CtrRenderer* r, uint32_t handle, TexturePageItem** outTpag, int32_t* w, int32_t* h) {
    *outTpag = nullptr;
    if (handle == 0) return false;
    if (handle & SURFACE_TEXTURE_FLAG) {
        CtrSurface* s = getSurface(r, (int32_t) (handle & ~SURFACE_TEXTURE_FLAG));
        if (s == nullptr) return false;
        *w = s->width;
        *h = s->height;
        return true;
    }
    CtrPage* page = acquireTpagPage(r, (int32_t) handle - 1, outTpag);
    if (page == nullptr) return false;
    *w = page->width;
    *h = page->height;
    return true;
}

static float ctrTextureGetTexelWidth(Renderer* renderer, uint32_t texHandle) {
    TexturePageItem* tpag;
    int32_t w = 0, h = 0;
    if (!textureHandleSize((CtrRenderer*) renderer, texHandle, &tpag, &w, &h) || 0 >= w) return 1.0f;
    return 1.0f / (float) w;
}

static float ctrTextureGetTexelHeight(Renderer* renderer, uint32_t texHandle) {
    TexturePageItem* tpag;
    int32_t w = 0, h = 0;
    if (!textureHandleSize((CtrRenderer*) renderer, texHandle, &tpag, &w, &h) || 0 >= h) return 1.0f;
    return 1.0f / (float) h;
}

static bool ctrTextureGetUVs(Renderer* renderer, uint32_t texHandle, float* outUVs) {
    TexturePageItem* tpag;
    int32_t w = 0, h = 0;
    if (!textureHandleSize((CtrRenderer*) renderer, texHandle, &tpag, &w, &h) || 0 >= w || 0 >= h) return false;
    if (tpag == nullptr) {
        outUVs[0] = 0.0f;
        outUVs[1] = 0.0f;
        outUVs[2] = 1.0f;
        outUVs[3] = 1.0f;
        return true;
    }
    outUVs[0] = (float) tpag->sourceX / (float) w;
    outUVs[1] = (float) tpag->sourceY / (float) h;
    outUVs[2] = outUVs[0] + (float) tpag->sourceWidth / (float) w;
    outUVs[3] = outUVs[1] + (float) tpag->sourceHeight / (float) h;
    return true;
}

// Only the samplers ctrShaderGetSamplerIndex gives out are used: the palette
// shaders' and the castle reflections', prophecy shaders', shd_shoujo's and
// shd_texscroll_ext's (kept in stageTex).
static void ctrTextureSetStage(Renderer* renderer, int32_t slot, uint32_t texHandle) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    if (0 < slot && 4 > slot && r->stageTex[slot] != texHandle) {
        if (prophecyBatches(r)) flushBatch(r);
        r->stageTex[slot] = texHandle;
    }
    if (slot != PAL_SAMPLER_SLOT || r->palTexture == texHandle) return;
    if (r->palKind != PAL_NONE) flushBatch(r);
    r->palTexture = texHandle;
    r->palDirty = true;
}

