// ===[ Screenshots ]===

static void writeLe32(uint8_t* p, uint32_t v) {
    p[0] = (uint8_t) v;
    p[1] = (uint8_t) (v >> 8);
    p[2] = (uint8_t) (v >> 16);
    p[3] = (uint8_t) (v >> 24);
}

// Allocates a 24-bit bottom-up BMP with its headers filled in.
#line 16010
static uint8_t* allocBmp(int32_t w, int32_t h, uint32_t* outRowBytes, uint32_t* outFileBytes) {
    uint32_t rowBytes = ((uint32_t) w * 3 + 3) & ~3u;
    uint32_t imageBytes = rowBytes * (uint32_t) h;
    uint8_t* bmp = safeCalloc(1, 54 + imageBytes);
    bmp[0] = 'B';
    bmp[1] = 'M';
    writeLe32(bmp + 2, 54 + imageBytes);
    writeLe32(bmp + 10, 54);
    writeLe32(bmp + 14, 40);
    writeLe32(bmp + 18, (uint32_t) w);
    writeLe32(bmp + 22, (uint32_t) h);
    bmp[26] = 1;
    bmp[28] = 24;
    writeLe32(bmp + 34, imageBytes);
    *outRowBytes = rowBytes;
    *outFileBytes = 54 + imageBytes;
    return bmp;
}

static bool writeFile(const char* path, const uint8_t* data, uint32_t size) {
    uint64_t start = svcGetSystemTick();
    FILE* f = fopen(path, "wb");
    bool ok = false;
    if (f != nullptr) {
        ok = fwrite(data, 1, size, f) == size;
        if (fclose(f) != 0) ok = false;
    }
    double ms = (double) (svcGetSystemTick() - start) / (double) (SYSCLOCK_ARM11 / 1000);
    if (ok) CtrLinkFiles_note(path); // goes to the PC at the end with --autoshot or --send-files
    if (ok) logInfo("Screenshot: saved %s (%.0f ms)\n", path, ms);
    else logWarn("Screenshot: failed to write %s (%.0f ms)\n", path, ms);
    return ok;
}

// Saves a screen as last presented. Framebuffers are portrait: each
// 240-pixel run is one screen column, bottom to top. The top screen is RGB8
// (stored B, G, R), 400 or 800 columns; the bottom screen is RGB565. Call
// with the GPU queue idle.
//
// citro3d swaps a screen's buffers at a VBlank after its transfer lands, and
// in Azahar the newest frame was still in the back buffer then: the buffer
// on screen held the frame before the application surface's (a shot of
// Lancer's battle matched the surface of one frame earlier, every frame of
