static void skipDrawLines(Renderer* renderer, const float* xy, int32_t count, float width, uint32_t color, float alpha) {
    if (0 >= count) return;
    bool draw;
    CtrSkipOp* op = skipBegin((CtrRenderer*) renderer, SR_LINES, xy, (size_t) count * 4 * sizeof(float), nullptr, 0, &draw);
    if (op != nullptr) {
        SKIP_F(op, width, alpha);
        op->i[1] = count;
        op->c[0] = color;
    } else if (draw) {
        ctrDrawLines(renderer, xy, count, width, color, alpha);
    } else {
        // Dropped ones count as the lines they stand for.
        ((CtrRenderer*) renderer)->skip.dropped += (uint32_t) count - 1;
    }
}

// Nothing on the application surface shows, so draw_circle needn't build its shape.
static bool skipRectOutsideView(Renderer* renderer, float x0, float y0, float x1, float y1) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    if (!r->skip.active) return ctrRectOutsideView(renderer, x0, y0, x1, y1);
    if (renderer->runner->applicationSurfaceId == r->boundSurface) return !r->skip.keepApp || ctrRectOutsideView(renderer, x0, y0, x1, y1);
    if (renderer->drawMuted && !r->skip.record) {
        CtrSurface* s = getSurface(r, r->boundSurface);
        if (s != nullptr && s->boundFrames >= 2 && !s->needsClear) return true;
    }
    return ctrRectOutsideView(renderer, x0, y0, x1, y1);
}

