// The surface behind a texture handle (surface_get_texture), or -1.
static int32_t skipHandleSurface(uint32_t handle) {
    return 0 != (handle & SURFACE_TEXTURE_FLAG) ? (int32_t) (handle & ~SURFACE_TEXTURE_FLAG) : -1;
}

static void skipPrimitiveEnd(Renderer* renderer) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    CtrSkipAction action = skipAction(r);
    if (action == SKIP_RECORD && 0 <= skipHandleSurface(r->primitiveTexture)) {
        // A surface's texture would be sampled when drawn, not as it is now.
        skipNoteUnrecordable(r, "primitive textured with a surface");
        skipGoLive(r, r->boundSurface);
        action = SKIP_DRAW;
    }
    if (action == SKIP_RECORD) {
        int32_t count = (int32_t) arrlen(r->primitiveVertices);
        CtrSkipOp* op = skipRecOp(r, r->boundSurface, SR_PRIMITIVE, r->primitiveVertices, (size_t) count * sizeof(CtrVertex), nullptr, 0);
        if (op != nullptr) {
            op->i[1] = r->primitiveType;
            op->i[2] = count;
            op->c[0] = r->primitiveTexture;
            arrsetlen(r->primitiveVertices, 0);
            return;
        }
        action = SKIP_DRAW;
    }
    if (action == SKIP_DROP) {
        arrsetlen(r->primitiveVertices, 0);
        return;
    }
    skipSyncRead(r, skipHandleSurface(r->primitiveTexture));
    ctrPrimitiveEnd(renderer);
}

static void skipDrawVertexBuffer(Renderer* renderer, VertexBuffer* buffer, int32_t primitive, int32_t texture, int32_t offset, int32_t number) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    CtrSkipAction action = skipAction(r);
    if (action == SKIP_DROP) return;
    if (action == SKIP_RECORD) {
        // The buffer may change before it would be drawn.
        skipNoteUnrecordable(r, "vertex buffer");
        skipGoLive(r, r->boundSurface);
    }
    if (0 < texture) skipSyncRead(r, skipHandleSurface((uint32_t) texture));
    ctrDrawVertexBuffer(renderer, buffer, primitive, texture, offset, number);
}

static void skipClearScreen(Renderer* renderer, uint32_t color, float alpha) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    int32_t id = r->boundSurface;
    CtrSurface* s = getSurface(r, id);
    bool whole = r->colorWrite[0] && r->colorWrite[1] && r->colorWrite[2] && r->colorWrite[3];
    if (r->skip.active && r->skip.record && renderer->drawMuted && whole && s != nullptr && id != renderer->runner->applicationSurfaceId &&
        s->boundFrames >= 2 && !s->needsClear && skipRecordable(r, s)) {
        // Nothing that waits there would show through: a recording that needs nothing of what it held starts.
        skipDiscard(r, s);
        s->skipLive = false;
        CtrSkipOp* op = skipRecOp(r, id, SR_CLEAR, nullptr, 0, nullptr, 0);
        if (op != nullptr) {
            op->c[0] = color;
            op->f[0] = alpha;
            getSurface(r, id)->skipRec->whole = true;
        } else {
            ctrClearScreen(renderer, color, alpha);
        }
        return;
    }
    if (whole && s != nullptr && s->skipRec != nullptr) {
        // Drawn now, on a shown frame or as the draw of an object that runs: what waits there would be cleared away.
        skipDiscard(r, s);
        s->skipLive = false;
    }
    bool draw;
    CtrSkipOp* op = skipBegin(r, SR_CLEAR, nullptr, 0, nullptr, 0, &draw);
    if (op != nullptr) {
        op->c[0] = color;
        op->f[0] = alpha;
    } else if (draw) {
        ctrClearScreen(renderer, color, alpha);
    }
}

static void skipDrawSpriteTiled(Renderer* renderer, int32_t tpagIndex, float originX, float originY, float x, float y, float xscale,
                                float yscale, bool tileX, bool tileY, float roomW, float roomH, uint32_t color, float alpha) {
    bool draw;
    CtrSkipOp* op = skipBegin((CtrRenderer*) renderer, SR_SPRITE_TILED, nullptr, 0, nullptr, 0, &draw);
    if (op != nullptr) {
        op->i[0] = tpagIndex;
        SKIP_F(op, originX, originY, x, y, xscale, yscale, roomW, roomH, alpha);
        op->flag = (uint8_t) ((tileX ? 1 : 0) | (tileY ? 2 : 0));
        op->c[0] = color;
    } else if (draw) {
        ctrDrawSpriteTiled(renderer, tpagIndex, originX, originY, x, y, xscale, yscale, tileX, tileY, roomW, roomH, color, alpha);
    }
}

// For the wrappers that draw a surface: the op recorded (fill it), or nullptr to draw it (true) or not (false).
static CtrSkipOp* skipReadOp(CtrRenderer* r, uint8_t kind, int32_t surfaceId, bool* draw) {
    *draw = true;
    CtrSkipAction action = skipAction(r);
    if (action == SKIP_DROP) {
        *draw = false;
        return nullptr;
    }
    if (action == SKIP_RECORD) {
        int32_t dest = r->boundSurface;
        CtrSkipRec* read = nullptr;
        int32_t how = skipRecordRead(r, dest, surfaceId, &read);
        if (how == 0) {
            *draw = false;
            return nullptr;
        }
        if (0 < how) {
            // Under shd_tower, the uniforms drawTowerStrips will want (i[6]).
            TowerUniforms uni;
            bool tower = r->shaderFx == SHADER_FX_TOWER;
            if (tower) towerUniforms(r, &uni);
            CtrSkipOp* op = skipRecOp(r, dest, kind, tower ? &uni : nullptr, tower ? sizeof(uni) : 0, nullptr, 0);
            if (op != nullptr) {
                op->i[0] = surfaceId;
                op->read = read;
                if (read != nullptr) getSurface(r, dest)->skipRec->reads++;
                return op;
            }
            skipReleaseRead(r, surfaceId, read);
        } else {
            skipNoteUnrecordable(r, "reads the application surface or a surface it can't record");
            skipGoLive(r, dest);
        }
    }
    noteAppRead(&r->base, surfaceId);
    skipSyncRead(r, surfaceId);
    return nullptr;
}

static void skipDrawSurface(Renderer* renderer, int32_t surfaceId, int32_t srcLeft, int32_t srcTop, int32_t srcWidth, int32_t srcHeight, float x,
                            float y, float xscale, float yscale, float angleDeg, uint32_t color, float alpha) {
    bool draw;
    CtrSkipOp* op = skipReadOp((CtrRenderer*) renderer, SR_SURFACE, surfaceId, &draw);
    if (op != nullptr) {
        op->i[1] = srcLeft;
        op->i[2] = srcTop;
        op->i[3] = srcWidth;
        op->i[4] = srcHeight;
        SKIP_F(op, x, y, xscale, yscale, angleDeg, alpha);
        op->c[0] = color;
        return;
    }
    if (draw) ctrDrawSurface(renderer, surfaceId, srcLeft, srcTop, srcWidth, srcHeight, x, y, xscale, yscale, angleDeg, color, alpha);
}

