// Once the display settings stop drawing natively, every native-scale
// surface is made full, for good, at the start of the next frame drawn: the
// player changed the Drawing setting to Full (or the top mode), and the
// game's surfaces would otherwise stay at half detail until it made them
// again.
static void promoteNativeSurfaces(CtrRenderer* r) {
    if (r->skip.active) return; // a skipped frame's copies are skipped too
    r->nativeCheck = false;
    if (nativeDisplay(r)) return;
    r->stereoDetail = false;
    remakeNativeSurfaces(r, true, false, "native drawing off");
}

// While 3D is shown (the right eye drawn, so the slider is up), each eye
// shows its own columns of the full-resolution frame (see nativeWanted), and
// a native-scale surface would show at half detail. At the first frame drawn
// with it every native-scale surface is made full, and surfaces made while
// it lasts are full (nativeScaleFor). They are made native-scale again only
// once the slider has been down for STEREO_DETAIL_SECONDS of game time, at
// the start of a frame, so a slider moved up and down doesn't remake them
// over and over. Counted in frames, not by the clock, so a run with a
// virtual clock does it at the same frame each time.
#define STEREO_DETAIL_SECONDS 2

static void updateStereoDetail(CtrRenderer* r) {
    if (r->skip.active) return; // stereoActive is still the frame before's
    if (r->stereoActive) r->stereoShownFrame = r->frame;
    if (r->stereoActive && !r->stereoDetail && nativeDisplay(r)) {
        r->stereoDetail = true;
        remakeNativeSurfaces(r, true, true, "3D shown");
        return;
    }
    if (!r->stereoDetail || r->stereoActive) return;
    double frames = STEREO_DETAIL_SECONDS * (double) Runner_getEffectiveGameSpeed(r->base.runner);
    if (frames > (double) (r->frame - r->stereoShownFrame)) return;
    r->stereoDetail = false;
    remakeNativeSurfaces(r, false, false, "3D off for 2 s");
}

