// Sets up copying the application surface (or an image made from it) onto
// the bound target as it is, alpha ignored, as GameMaker draws the
// application surface. Set after bindTarget: binding a screen splits the
// frame, which puts the game's blend state back, and drawing with it would
// darken every pixel whose alpha isn't 255 (bm_subtract zeroes alpha, and
// alpha blending leaves it below 255).
static void copyState(CtrRenderer* r) {
    C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_ONE, GPU_ZERO, GPU_ONE, GPU_ZERO);
    C3D_AlphaTest(false, GPU_ALWAYS, 0);
    C3D_DepthTest(false, GPU_ALWAYS, GPU_WRITE_COLOR);
    // Left so: the next frame starts by putting the game's back.
    r->plainTexEnv = true;
    applyTexEnv(r);
    r->plainTexEnv = false;
    C3D_SetScissor(GPU_SCISSOR_DISABLE, 0, 0, 0, 0);
}

// Screen pixels on the bound screen target. Screen targets are portrait
// buffers, so the projection is tilted.
static void screenProjection(CtrRenderer* r) {
    int32_t screenW = r->boundTarget->frameBuf.height;
    ownViewport(r, 0, 0, TOP_SCREEN_H, (u32) screenW);
    C3D_Mtx m;
    Mtx_OrthoTilt(&m, 0.0f, (float) screenW, (float) TOP_SCREEN_H, 0.0f, 1.0f, -1.0f, true);
    uploadProjection(r, &m);
}

// Draws the application surface (srcX..srcX+srcW texels, shifted by offX/offY
// texels) into dst on the bound screen target.
static void blitApp(CtrRenderer* r, C3D_Tex* tex, float srcX, float srcY, float srcW, float srcH, float offX, float offY, const float* dst,
                    bool linear) {
    copyState(r);
    screenProjection(r);
    float px[4] = { dst[0], dst[0] + dst[2], dst[0] + dst[2], dst[0] };
    float py[4] = { dst[1], dst[1], dst[1] + dst[3], dst[1] + dst[3] };
    CtrColor white = { 255, 255, 255, 255 };
    CtrColor cs[4] = { white, white, white, white };
    float tw = (float) tex->width, th = (float) tex->height;
    r->filterOverride = linear ? FILTER_LINEAR : FILTER_NEAREST;
    emitQuad(r, tex, px, py, (srcX + offX) / tw, (srcY + offY) / th, (srcX + srcW + offX) / tw, (srcY + srcH + offY) / th, cs);
    flushBatch(r);
    r->filterOverride = 0;
}

// Texel shift that makes a scaled-down image sample the first texel under
// each screen pixel instead of the boundary between the middle two.
static float firstTexelOffset(float scale) {
    return 0.5f - 0.5f / scale;
}

// ===[ Detail-keeping shrink ]===
//
// Without smoothing, halving the application surface shows the first texel
// of each 2x2 block, so a line or dot one texel wide on an odd column or row
// vanished: the graze outline broke up, and small text lost strokes. Now
// each pair of texels a, b (with c after them, and y, x before) shows b
// when b stands alone, differing from a and from c, which would otherwise
// show it, and a matches y and x, so it isn't the end of a stroke that only
// this pixel can show (". # # . #" kept the gap and lost the stroke).
// Everything else keeps the first texel, so strokes two or more texels wide
// come out one pixel wide as before (none get bolder), and art drawn at 2x
// shows exactly what it did on either alignment. Detail finer than a screen
// pixel, such as a notch one texel deep, still can't show; smoothing shows
// it as a blend.
//
// It is separable: columns first (into an image of half the width), then
// rows (onto the screen), each in two draws on the texture combiner over
// the same image one texel apart. The pick draw (a, b, c on textures 0 to
// 2):
//
//   stage 0: 0.5 + (b - a) / 2
//   stage 1: d1 = 4 |b - a|^2 (dot3), kept in the combiner buffer
//   stages 2, 3: d2 = 4 |b - c|^2 the same way
//   stage 4: s = 4 d1 d2, clamped to [0, 1]
//   stage 5: a + s (b - a)
//
// then the keep draw, blended over it by its alpha (a on texture 0, and on
// texture 1 the average m of y and x, by linear filtering):
//
//   stages 0, 1: e = 4 |a - m|^2 (dot3) as above
//   stages 2, 3: 8 e, clamped: the alpha, so a comes out unless x and y
//   both match it.
//
// A pair that differs by a fifth of full brightness in every channel or
// more switches all the way; fainter detail blends. The half-width image
// goes through in strips, alternately in the two halves of one 384 KB VRAM
// texture, each with the two rows before it and the one after; while the
// surfaces need that VRAM, the frame is halved the old way. In stereo
// HD, where the eyes take alternate columns, and in the wide modes, only
// rows are halved, straight from the application surface, and nothing is
// allocated. Smoothing keeps its 2x2 average; depth mode keeps the first
// texel.
#define SHRINK_STRIP_W 512
#define SHRINK_STRIP_H 256
#define SHRINK_STRIP_ROWS 124 // application surface rows per strip: even, and with three more in half the texture
#define SHRINK_VRAM_BYTES (SHRINK_STRIP_W * SHRINK_STRIP_H * 3)
#define SHRINK_VRAM_MARGIN (1024 * 1024) // left for surfaces

enum { SHRINK_NONE, SHRINK_PICK, SHRINK_KEEP };

// Whether the half-width strip texture is there or can be made, short of
// taking the last of VRAM from the surfaces.
static bool ensureShrinkStrip(CtrRenderer* r) {
    if (r->shrink.ready) return true;
    if (0 < (int32_t) (r->shrink.retryFrame - r->frame)) return false;
    r->shrink.retryFrame = r->frame + SHRINK_RETRY_FRAMES;
    // Tiles' copies in VRAM make way (see "Tiles in VRAM").
    while (SHRINK_VRAM_BYTES + SHRINK_VRAM_MARGIN > vramSpaceFree() && yieldMirrors(r, SHRINK_VRAM_BYTES + SHRINK_VRAM_MARGIN)) {}
    if (SHRINK_VRAM_BYTES + SHRINK_VRAM_MARGIN > vramSpaceFree()) {
        logInfo("Renderer: %.0f KB of VRAM free, halving the frame without the detail-keeping shrink for now\n",
                (double) vramSpaceFree() / 1024.0);
        return false;
    }
    return makeShrinkStrip(r);
}

// Makes the half-width strip texture, with no margin left for surfaces:
// reclaimVram also uses this to put it back when freeing it made no room.
static bool makeShrinkStrip(CtrRenderer* r) {
    C3D_Tex* tex = &r->shrink.strip;
    while (!C3D_TexInitVRAM(tex, SHRINK_STRIP_W, SHRINK_STRIP_H, GPU_RGB8)) {
        if (!yieldMirrors(r, SHRINK_VRAM_BYTES)) return false;
    }
    C3D_TexSetWrap(tex, GPU_CLAMP_TO_EDGE, GPU_CLAMP_TO_EDGE);
    r->shrink.stripTarget = C3D_RenderTargetCreateFromTex(tex, GPU_TEXFACE_2D, 0, -1);
    if (r->shrink.stripTarget == nullptr) {
        C3D_TexDelete(tex);
        return false;
    }
    r->shrink.ready = true;
    return true;
}

// The VRAM tiles' copies leave free for the strip texture, until it is made.
static uint32_t shrinkVramWanted(const CtrRenderer* r) {
    return r->shrink.ready ? 0u : SHRINK_VRAM_BYTES + SHRINK_VRAM_MARGIN;
}

// Starts a pick or keep batch (see drawShrinkBatch): the quads emitted until
// endShrinkBatch have a at their texture coordinates, and b (or m) at tc1
// and c at tc2 from them.
static void beginShrinkBatch(CtrRenderer* r, uint8_t mode, const float* tc1, const float* tc2) {
    flushBatch(r);
    memcpy(r->shrink.tc1, tc1, sizeof(r->shrink.tc1));
    memcpy(r->shrink.tc2, tc2, sizeof(r->shrink.tc2));
    r->shrink.batchMode = mode;
    r->filterOverride = FILTER_NEAREST; // which also keeps the batch to one texture
}

static void emitShrinkQuad(CtrRenderer* r, C3D_Tex* tex, float x0, float y0, float x1, float y1, float u0, float v0, float u1, float v1) {
    float px[4] = { x0, x1, x1, x0 };
    float py[4] = { y0, y0, y1, y1 };
    CtrColor white = { 255, 255, 255, 255 };
    CtrColor cs[4] = { white, white, white, white };
    emitQuad(r, tex, px, py, u0, v0, u1, v1, cs);
}

static void endShrinkBatch(CtrRenderer* r) {
    flushBatch(r);
    r->filterOverride = 0;
    r->shrink.batchMode = SHRINK_NONE;
}

// Sets env to 0.5 + (t1 - t0) / 2, alpha 1.
static void shrinkHalfDifference(C3D_TexEnv* env, GPU_TEVSRC t1, GPU_TEVSRC t0) {
    C3D_TexEnvInit(env);
    C3D_TexEnvSrc(env, C3D_RGB, t1, t0, GPU_CONSTANT);
    C3D_TexEnvOpRgb(env, GPU_TEVOP_RGB_SRC_COLOR, GPU_TEVOP_RGB_ONE_MINUS_SRC_COLOR, GPU_TEVOP_RGB_SRC_COLOR);
    C3D_TexEnvFunc(env, C3D_RGB, GPU_INTERPOLATE);
    C3D_TexEnvSrc(env, C3D_Alpha, GPU_CONSTANT, 0, 0);
    C3D_TexEnvFunc(env, C3D_Alpha, GPU_REPLACE);
    C3D_TexEnvColor(env, 0xFF808080u);
}

// Sets env to 4 |previous - 0.5|^2 * 4 (dot3), clamped.
static void shrinkSquare(C3D_TexEnv* env) {
    C3D_TexEnvInit(env);
    C3D_TexEnvSrc(env, C3D_RGB, GPU_PREVIOUS, GPU_PREVIOUS, 0);
    C3D_TexEnvFunc(env, C3D_RGB, GPU_DOT3_RGB);
    C3D_TexEnvScale(env, C3D_RGB, GPU_TEVSCALE_4);
}

// Draws the pending pick or keep batch.
static void drawShrinkBatch(CtrRenderer* r, uint32_t count) {
    C3D_Tex* tex = r->batchTex;
    C3D_TexSetFilter(tex, GPU_NEAREST, GPU_NEAREST);
    bool keep = r->shrink.batchMode == SHRINK_KEEP;

    C3D_TexEnv saved[6], envs[6];
    for (int32_t i = 0; 6 > i; i++) {
        saved[i] = *C3D_GetTexEnv(i);
        C3D_TexEnvInit(&envs[i]);
    }
    if (keep) {
        shrinkHalfDifference(&envs[0], GPU_TEXTURE0, GPU_TEXTURE1);
        shrinkSquare(&envs[1]);
        C3D_TexEnvScale(&envs[2], C3D_RGB, GPU_TEVSCALE_4);
        C3D_TexEnvSrc(&envs[3], C3D_RGB, GPU_TEXTURE0, 0, 0);
        C3D_TexEnvOpAlpha(&envs[3], GPU_TEVOP_A_SRC_R, GPU_TEVOP_A_SRC_ALPHA, GPU_TEVOP_A_SRC_ALPHA);
        C3D_TexEnvScale(&envs[3], C3D_Alpha, GPU_TEVSCALE_2);
        r->shrink.linear = *tex;
        C3D_TexSetFilter(&r->shrink.linear, GPU_LINEAR, GPU_LINEAR);
    } else {
        shrinkHalfDifference(&envs[0], GPU_TEXTURE1, GPU_TEXTURE0);
        shrinkSquare(&envs[1]);
        shrinkHalfDifference(&envs[2], GPU_TEXTURE1, GPU_TEXTURE2);
        shrinkSquare(&envs[3]);
        C3D_TexEnvSrc(&envs[4], C3D_RGB, GPU_PREVIOUS, GPU_PREVIOUS_BUFFER, 0);
        C3D_TexEnvFunc(&envs[4], C3D_RGB, GPU_MODULATE);
        C3D_TexEnvScale(&envs[4], C3D_RGB, GPU_TEVSCALE_4);
        C3D_TexEnvSrc(&envs[5], C3D_RGB, GPU_TEXTURE1, GPU_TEXTURE0, GPU_PREVIOUS);
        C3D_TexEnvFunc(&envs[5], C3D_RGB, GPU_INTERPOLATE);
    }

    C3D_BindProgram(r->pairProgram);
    C3D_FVUnifSet(GPU_VERTEX_SHADER, r->pairTc1Loc, r->shrink.tc1[0], r->shrink.tc1[1], r->shrink.tc1[2], r->shrink.tc1[3]);
    C3D_FVUnifSet(GPU_VERTEX_SHADER, r->pairTc2Loc, r->shrink.tc2[0], r->shrink.tc2[1], r->shrink.tc2[2], r->shrink.tc2[3]);
    C3D_TexBind(0, tex);
    C3D_TexBind(1, keep ? &r->shrink.linear : tex);
    if (!keep) C3D_TexBind(2, tex);
    for (int32_t i = 0; 6 > i; i++) *C3D_GetTexEnv(i) = envs[i];
    // The pick draw reads stage 1's result back at stage 4.
    if (!keep) C3D_TexEnvBufUpdate(C3D_Both, 1 << 1);
    if (keep) C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_SRC_ALPHA, GPU_ONE_MINUS_SRC_ALPHA, GPU_ZERO, GPU_ONE);
    drawRange(r, (int) r->batchStart, (int) count);
    if (keep) C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_ONE, GPU_ZERO, GPU_ONE, GPU_ZERO); // as copyState
    if (!keep) C3D_TexEnvBufUpdate(C3D_Both, r->texEnvBufUsed ? 1 : 0);
    for (int32_t i = 0; 6 > i; i++) *C3D_GetTexEnv(i) = saved[i];
    // As drawMultiBatch: units 1 and 2 are turned off by the next draw.
    for (uint32_t k = 1; 3 > k; k++) {
        CITRO_TEX(k) = nullptr;
        CITRO_FLAGS |= CITRO_FLAG_TEX0 << k;
    }
    C3D_BindProgram(r->batchProgram);
    r->citroCleanValid = false;
}

// The top screen in Standard mode: columns into a strip, then rows onto the
// screen at dst, a strip at a time.
static void shrinkBoth(CtrRenderer* r, C3D_Tex* app, float appW, float appH, const float* dst) {
    C3D_Tex* strip = &r->shrink.strip;
    float aw = (float) app->width, ah = (float) app->height;
    float sw = (float) strip->width, sh = (float) strip->height;
    float n = appW * 0.5f;             // columns out
    float ue = (2.0f * n - 2.5f) / aw; // the last column's a
    float none[4] = { 1.0f, 1.0f, 0.0f, 0.0f };
    for (int32_t k = 0; (float) (k * SHRINK_STRIP_ROWS) < appH; k++) {
        float y0 = (float) (k * SHRINK_STRIP_ROWS), y1 = fminf(appH, y0 + (float) SHRINK_STRIP_ROWS);
        float rows = y1 - y0;
        float top = (float) ((k & 1) * (SHRINK_STRIP_H / 2));
        // Rows y0 - 2 to y1 (the last row again at the bottom; above the
        // top, the texture's edge repeats the first) into strip rows top
        // onwards, column i from columns 2i - 2 to 2i + 2. The last column
        // has no c, so it gets b there: it keeps a.
        bindTarget(r, r->shrink.stripTarget, -1);
        copyState(r);
        ownViewport(r, 0, 0, strip->width, strip->height);
        C3D_Mtx m;
        pixelProjection(&m, sw, sh);
        uploadProjection(r, &m);
        float next = y1 < appH ? y1 : appH - 1.0f;
        float yb = top + 2.0f + rows; // the strip row after
        for (int32_t edge = 0; 2 > edge; edge++) {
            float x0 = edge ? n - 1.0f : 0.0f, x1 = edge ? n : n - 1.0f;
            float u0 = edge ? ue : -0.5f / aw, u1 = edge ? ue + 2.0f / aw : ue;
            float tc1[4] = { 1.0f, 1.0f, 1.0f / aw, 0.0f };
            float tc2[4] = { 1.0f, 1.0f, (edge ? 1.0f : 2.0f) / aw, 0.0f };
            beginShrinkBatch(r, SHRINK_PICK, tc1, tc2);
            emitShrinkQuad(r, app, x0, top, x1, yb, u0, (y0 - 2.0f) / ah, u1, y1 / ah);
            emitShrinkQuad(r, app, x0, yb, x1, yb + 1.0f, u0, next / ah, u1, (next + 1.0f) / ah);
            endShrinkBatch(r);
        }
        float mTc[4] = { 1.0f, 1.0f, -1.5f / aw, 0.0f };
        beginShrinkBatch(r, SHRINK_KEEP, mTc, none);
        emitShrinkQuad(r, app, 0.0f, top, n, yb, -0.5f / aw, (y0 - 2.0f) / ah, ue + 2.0f / aw, y1 / ah);
        emitShrinkQuad(r, app, 0.0f, yb, n, yb + 1.0f, -0.5f / aw, next / ah, ue + 2.0f / aw, (next + 1.0f) / ah);
        endShrinkBatch(r);
        splitFrame(r);
        // Strip rows 2j to 2j + 2 (and the two before) onto screen row j.
        bindTarget(r, r->topTarget, -1);
        copyState(r);
        screenProjection(r);
        float sx0 = dst[0], sx1 = dst[0] + dst[2], sy0 = dst[1] + y0 * 0.5f, sy1 = dst[1] + y1 * 0.5f;
        float sv0 = (top + 1.5f) / sh, sv1 = (yb - 0.5f) / sh;
        float tc1[4] = { 1.0f, 1.0f, 0.0f, 1.0f / sh };
        float tc2[4] = { 1.0f, 1.0f, 0.0f, 2.0f / sh };
        beginShrinkBatch(r, SHRINK_PICK, tc1, tc2);
        emitShrinkQuad(r, strip, sx0, sy0, sx1, sy1, 0.0f, sv0, n / sw, sv1);
        endShrinkBatch(r);
        float smTc[4] = { 1.0f, 1.0f, 0.0f, -1.5f / sh };
        beginShrinkBatch(r, SHRINK_KEEP, smTc, none);
        emitShrinkQuad(r, strip, sx0, sy0, sx1, sy1, 0.0f, sv0, n / sw, sv1);
        endShrinkBatch(r);
    }
}

// Stereo HD and the wide modes: rows 2j - 2 to 2j + 2 of the application
// surface onto row j of the bound screen, columns shifted by offX texels.
// The last row has no c, so it gets b there: it keeps a.
static void shrinkRows(CtrRenderer* r, C3D_Tex* app, float appW, float appH, float offX, const float* dst) {
    float aw = (float) app->width, ah = (float) app->height;
    copyState(r);
    screenProjection(r);
    float u0 = offX / aw, u1 = (appW + offX) / aw;
    float x0 = dst[0], x1 = dst[0] + dst[2], yl = dst[1] + dst[3] - 1.0f;
    float vl = (appH - 2.5f) / ah; // the last row's a
    float tc1[4] = { 1.0f, 1.0f, 0.0f, 1.0f / ah };
    float tc2[4] = { 1.0f, 1.0f, 0.0f, 2.0f / ah };
    beginShrinkBatch(r, SHRINK_PICK, tc1, tc2);
    emitShrinkQuad(r, app, x0, dst[1], x1, yl, u0, -0.5f / ah, u1, vl);
    endShrinkBatch(r);
    beginShrinkBatch(r, SHRINK_PICK, tc1, tc1);
    emitShrinkQuad(r, app, x0, yl, x1, yl + 1.0f, u0, vl, u1, vl + 2.0f / ah);
    endShrinkBatch(r);
    float mTc[4] = { 1.0f, 1.0f, 0.0f, -1.5f / ah };
    float none[4] = { 1.0f, 1.0f, 0.0f, 0.0f };
    beginShrinkBatch(r, SHRINK_KEEP, mTc, none);
    emitShrinkQuad(r, app, x0, dst[1], x1, yl + 1.0f, u0, -0.5f / ah, u1, vl + 2.0f / ah);
    endShrinkBatch(r);
}

// Smart smoothing at full resolution: the detail-keeping shrink leaves the
// averaged draws alone. The first pixel of each 2x2 block of such a draw
// holds the block's average (see "Smart smoothing"), but the second holds
// the average of a pair that straddles two blocks, and where that stood
// alone the shrink showed it (a stroke two texels wide after a gap, as in
// small text), 64 to 128 levels off. Each box of the frame's fine draws, in
// whole blocks, is drawn again over what the shrink made, its first texels
// as they are, as native drawing shows its averages. What else lies in a
// box (up to a quarter more, where boxes merged) shows its first texels
// too. A draw past SMART_BOXES_MAX has no box and stays to the shrink.
// offX, offY: the first texel's shift (firstTexelOffset) in each axis.
static void smartShowBoxes(CtrRenderer* r, const CtrSurface* app, C3D_Tex* tex, const float* dst, float scaleX, float scaleY, float offX,
                           float offY) {
    if (r->smart.shownVersion != app->version) {
        r->smart.shownVersion = app->version;
        r->smart.shownCount = r->smart.count;
        memcpy(r->smart.shown, r->smart.box, (size_t) r->smart.count * sizeof(r->smart.box[0]));
    }
    if (r->smart.shownCount == 0) return;
    copyState(r);
    screenProjection(r);
    CtrColor white = { 255, 255, 255, 255 };
    CtrColor cs[4] = { white, white, white, white };
    float tw = (float) tex->width, th = (float) tex->height;
    r->filterOverride = FILTER_NEAREST;
    for (int32_t i = 0; r->smart.shownCount > i; i++) {
        const int32_t* b = r->smart.shown[i];
        float x0 = dst[0] + (float) b[0] * scaleX, x1 = dst[0] + (float) b[2] * scaleX;
        float y0 = dst[1] + (float) b[1] * scaleY, y1 = dst[1] + (float) b[3] * scaleY;
        float px[4] = { x0, x1, x1, x0 }, py[4] = { y0, y0, y1, y1 };
        emitQuad(r, tex, px, py, ((float) b[0] + offX) / tw, ((float) b[1] + offY) / th, ((float) b[2] + offX) / tw, ((float) b[3] + offY) / th,
                 cs);
    }
    flushBatch(r);
    r->filterOverride = 0;
}

// Follows this frame's small text with the bottom screen. The view only moves
// as far as it must to keep the text in sight, so a growing line of
// typewriter text doesn't make it jump around. Text that is new or changing
// wins over labels that have been on screen unchanged for a while; once it
// stops changing, the view stays on it for up to 20 seconds while the rest
// of the small text is static.
static void updateMagnifier(CtrRenderer* r, int32_t appW, int32_t appH) {
    const float pad = 12.0f;
    if (!r->smallTextValid) {
        if (r->magnifier.active && --r->magnifier.holdFrames <= 0) r->magnifier.active = false;
        return;
    }
    const float* text = r->smallText;
    if (r->freshTextValid) {
        text = r->freshText;
        r->magnifier.lastFreshFrame = r->frame;
    } else if (r->magnifier.active && r->frame - r->magnifier.lastFreshFrame < 600) {
        r->magnifier.holdFrames = 45;
        return;
    }
    float x0 = text[0] - pad, y0 = text[1] - pad;
    float x1 = text[2] + pad, y1 = text[3] + pad;
    float fit = fminf((float) BOTTOM_SCREEN_W / (x1 - x0), (float) BOTTOM_SCREEN_H / (y1 - y0));
    if (fit > 1.0f) fit = 1.0f;
    if (fit < 0.5f) fit = 0.5f;

    float viewW, viewH;
    bool outside = true;
    if (r->magnifier.active) {
        viewW = (float) BOTTOM_SCREEN_W / r->magnifier.scale;
        viewH = (float) BOTTOM_SCREEN_H / r->magnifier.scale;
        outside = x1 < r->magnifier.x || r->magnifier.x + viewW < x0 || y1 < r->magnifier.y || r->magnifier.y + viewH < y0;
    }
    if (outside) {
        r->magnifier.active = true;
        r->magnifier.scale = fit;
        // Leave room above and to the left for a speech bubble's edge and
        // tail; typewriter text then grows into the rest of the screen.
        r->magnifier.x = text[0] - 56.0f;
        r->magnifier.y = text[1] - 28.0f;
    } else if (fit < r->magnifier.scale) {
        r->magnifier.scale = fit; // zoom out for longer text, never back in while it's shown
    }
    r->magnifier.holdFrames = 45;

    viewW = (float) BOTTOM_SCREEN_W / r->magnifier.scale;
    viewH = (float) BOTTOM_SCREEN_H / r->magnifier.scale;
    if (x1 > r->magnifier.x + viewW) r->magnifier.x = x1 - viewW;
    if (x0 < r->magnifier.x) r->magnifier.x = x0;
    if (y1 > r->magnifier.y + viewH) r->magnifier.y = y1 - viewH;
    if (y0 < r->magnifier.y) r->magnifier.y = y0;
    if (r->magnifier.x > (float) appW - viewW) r->magnifier.x = (float) appW - viewW;
    if (r->magnifier.y > (float) appH - viewH) r->magnifier.y = (float) appH - viewH;
    if (r->magnifier.x < 0.0f) r->magnifier.x = 0.0f;
    if (r->magnifier.y < 0.0f) r->magnifier.y = 0.0f;
    r->magnifier.x = floorf(r->magnifier.x);
    r->magnifier.y = floorf(r->magnifier.y);
}

// ===[ Dialogue on the bottom screen ]===
//
// With display.dialogueBottom, what the dialogue objects (ctr_dialogue.h)
// draw on the application surface outside battles is recorded instead of
// drawn, the way draws onto a recorded surface are (recordingSurface), in
// application surface pixels. The top screen so shows the scene without the
// box, and present() draws the recording on the bottom screen. The scale is
// the top screen's, half the application surface: UNDERTALE's 320x240 rooms
// and DELTARUNE's Light World come out 1:1, and DELTARUNE's Dark World text
// and portraits, drawn at 2x, keep every pixel. The texture pages are sampled
// directly rather than shrunk with the frame, so the text is as sharp as the
// art allows. Draws a recording can't hold (vertex buffers, primitives,
// surfaces) and draws under another blend mode or a shader stay on the top
// screen. The game makes the same draw calls either way; only where they
