// What the magnifier did with the bottom screen since the last call.
static void logMagnifierStats(CtrRenderer* r) {
    uint32_t frames = r->magnifier.shownFrames + r->magnifier.blankFrames + r->magnifier.keptFrames;
    if (frames > 0) {
        logInfo("Renderer: magnifier over %u frames: %u showed text, %u sent the blank bottom screen, %u left it as it was\n", (unsigned) frames,
                (unsigned) r->magnifier.shownFrames, (unsigned) r->magnifier.blankFrames, (unsigned) r->magnifier.keptFrames);
    }
    r->magnifier.shownFrames = r->magnifier.blankFrames = r->magnifier.keptFrames = 0;
}

