CtrSkipStats CtrRenderer_takeSkipStats(Renderer* renderer) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    CtrSkipStats stats = { r->skip.skipped, r->skip.dropped, r->skip.staleReads, r->skip.muted,
                           r->skip.workFrames, r->skip.workDraws, r->skip.workCommands, r->skip.workFills,
                           r->skip.workCopies, r->skip.behind };
    r->skipTaken.skipped += stats.skipped;
    r->skipTaken.dropped += stats.dropped;
    r->skipTaken.staleReads += stats.staleReads;
    r->skipTaken.muted += stats.muted;
    r->skipTaken.workFrames += stats.workFrames;
    r->skipTaken.workDraws += stats.workDraws;
    r->skipTaken.workCommands += stats.workCommands;
    r->skipTaken.workFills += stats.workFills;
    r->skipTaken.workCopies += stats.workCopies;
    r->skipTaken.behind += stats.behind;
    r->skip.skipped = r->skip.dropped = r->skip.staleReads = r->skip.muted = 0;
    r->skip.workFrames = r->skip.workDraws = r->skip.workCommands = r->skip.workFills = r->skip.workCopies = r->skip.behind = 0;
    return stats;
}

CtrSkipStats CtrRenderer_getSkipTotals(Renderer* renderer) {
    CtrRenderer* r = (CtrRenderer*) renderer;
    CtrSkipStats totals = { r->skipTaken.skipped + r->skip.skipped, r->skipTaken.dropped + r->skip.dropped,
                            r->skipTaken.staleReads + r->skip.staleReads, r->skipTaken.muted + r->skip.muted,
                            r->skipTaken.workFrames + r->skip.workFrames, r->skipTaken.workDraws + r->skip.workDraws,
                            r->skipTaken.workCommands + r->skip.workCommands, r->skipTaken.workFills + r->skip.workFills,
                            r->skipTaken.workCopies + r->skip.workCopies, r->skipTaken.behind + r->skip.behind };
    return totals;
}

